// Curated knowledge questions. Original wording; facts checked.
window.AGO_FACTS = [
  // ===================== CHANT =====================
  { id: "chant-001", topic: "chant", levels: ["ChM"], q: "What is the final of Mode 1 (Dorian)?", choices: ["E", "D", "F", "G"], answer: 1, explain: "The four finals of the eight-mode system are D (modes 1-2), E (3-4), F (5-6) and G (7-8).", difficulty: 1 },
  { id: "chant-002", topic: "chant", levels: ["ChM"], q: "What is the reciting tone (dominant) of Mode 1?", choices: ["A", "F", "C", "G"], answer: 0, explain: "Authentic modes generally recite a fifth above the final: D to A in Mode 1.", difficulty: 1 },
  { id: "chant-003", topic: "chant", levels: ["ChM"], q: "What is the reciting tone of Mode 2 (Hypodorian)?", choices: ["A", "D", "E", "F"], answer: 3, explain: "Plagal modes generally recite a third below the dominant of their authentic partner; Mode 2 recites on F.", difficulty: 2 },
  { id: "chant-004", topic: "chant", levels: ["ChM"], q: "In the medieval system the reciting tone of Mode 3 (Phrygian) is normally which pitch?", choices: ["A", "G", "C", "D"], answer: 2, explain: "A fifth above E would be B, an unstable pitch, so Mode 3's dominant was moved up to C.", difficulty: 2 },
  { id: "chant-005", topic: "chant", levels: ["ChM"], q: "What is the reciting tone of Mode 4 (Hypophrygian)?", choices: ["G", "A", "D", "F"], answer: 1, explain: "Mode 4 has its final on E and recites on A.", difficulty: 2 },
  { id: "chant-006", topic: "chant", levels: ["ChM"], q: "Mode 5 (Lydian) has which final and reciting tone?", choices: ["F and C", "F and A", "G and D", "E and C"], answer: 0, explain: "Mode 5: final F, dominant C (a fifth above).", difficulty: 1 },
  { id: "chant-007", topic: "chant", levels: ["ChM"], q: "What is the reciting tone of Mode 6 (Hypolydian)?", choices: ["C", "G", "D", "A"], answer: 3, explain: "Mode 6 has final F and recites on A, a third above the final.", difficulty: 2 },
  { id: "chant-008", topic: "chant", levels: ["ChM"], q: "What is the reciting tone of Mode 7 (Mixolydian)?", choices: ["B", "C", "D", "A"], answer: 2, explain: "Mode 7 has final G and recites a fifth above, on D.", difficulty: 1 },
  { id: "chant-009", topic: "chant", levels: ["ChM"], q: "What is the reciting tone of Mode 8 (Hypomixolydian)?", choices: ["D", "C", "A", "E"], answer: 1, explain: "Mode 8's expected dominant B was raised to C, just as in Mode 3.", difficulty: 2 },
  { id: "chant-010", topic: "chant", levels: ["ChM"], q: "Which mode is the plagal partner of the Mixolydian, sharing its final G?", choices: ["Mode 8", "Mode 6", "Mode 4", "Mode 2"], answer: 0, explain: "Even-numbered modes are plagal (the 'hypo-' modes); Mode 8 is Hypomixolydian.", difficulty: 1 },
  { id: "chant-011", topic: "chant", levels: ["ChM"], q: "How does the typical range (ambitus) of a plagal mode relate to its final?", choices: ["It runs from the final up an octave", "It lies entirely above the dominant", "It spans two octaves centered on the final", "It lies roughly a fourth below to a fifth above the final"], answer: 3, explain: "Authentic modes run roughly from the final to the octave above; plagal modes place the final in the middle of the range.", difficulty: 2 },
  { id: "chant-012", topic: "chant", levels: ["ChM"], q: "A two-note neume in which the lower note comes first is called a:", choices: ["Clivis", "Torculus", "Podatus (pes)", "Climacus"], answer: 2, explain: "The podatus or pes ascends; the clivis is its descending counterpart.", difficulty: 1 },
  { id: "chant-013", topic: "chant", levels: ["ChM"], q: "A two-note neume that descends (high, then low) is called a:", choices: ["Podatus", "Clivis", "Scandicus", "Porrectus"], answer: 1, explain: "The clivis is a descending two-note neume.", difficulty: 1 },
  { id: "chant-014", topic: "chant", levels: ["ChM"], q: "A three-note neume moving low-high-low is a:", choices: ["Torculus", "Porrectus", "Scandicus", "Climacus"], answer: 0, explain: "The torculus rises then falls; the porrectus does the opposite (high-low-high).", difficulty: 2 },
  { id: "chant-015", topic: "chant", levels: ["ChM"], q: "A three-note neume moving high-low-high, often drawn with a diagonal stroke, is a:", choices: ["Torculus", "Salicus", "Climacus", "Porrectus"], answer: 3, explain: "The porrectus's first two notes are written as a slanted line from the high to the low pitch.", difficulty: 2 },
  { id: "chant-017", topic: "chant", levels: ["ChM"], q: "In Solesmes practice, what happens to the note immediately before a quilisma?", choices: ["It is omitted", "It is sung with vibrato", "It is lengthened", "It is sung staccato"], answer: 2, explain: "The quilisma (jagged note) itself is light; the Solesmes method lengthens the note preceding it.", difficulty: 2 },
  { id: "chant-018", topic: "chant", levels: ["ChM"], q: "Smaller printed notes in square notation that occur on diphthongs or certain consonants (l, m, n, etc.) are called:", choices: ["Quilismas", "Liquescents", "Episemas", "Custodes"], answer: 1, explain: "Liquescent neumes reflect a gliding, semi-voiced passage between syllables.", difficulty: 2 },
  { id: "chant-019", topic: "chant", levels: ["ChM"], q: "How many lines does the staff of standard Gregorian square notation have?", choices: ["Four", "Three", "Five", "Six"], answer: 0, explain: "Square notation uses a four-line staff with movable C (do) or F (fa) clefs.", difficulty: 1 },
  { id: "chant-020", topic: "chant", levels: ["ChM"], q: "The small note at the end of a line of chant, showing the first pitch of the next line, is the:", choices: ["Punctum", "Virga", "Episema", "Custos"], answer: 3, explain: "The custos (guide) helps singers anticipate the next line's first pitch.", difficulty: 2 },
  { id: "chant-022", topic: "chant", levels: ["ChM"], q: "Which of these is NOT one of the Proper chants of the Mass?", choices: ["Introit", "Offertory", "Kyrie", "Communion"], answer: 2, explain: "The Kyrie belongs to the Ordinary, whose texts are invariable; the Proper changes with the day.", difficulty: 1 },
  { id: "chant-023", topic: "chant", levels: ["ChM"], q: "In the traditional Roman rite, which chant replaces the Alleluia during Lent?", choices: ["Gradual", "Tract", "Sequence", "Offertory"], answer: 1, explain: "The Tract, usually psalm verses sung without refrain, replaces the Alleluia in penitential seasons.", difficulty: 1 },
  { id: "chant-024", topic: "chant", levels: ["ChM"], q: "Which sequence is proper to Pentecost?", choices: ["Veni Sancte Spiritus", "Victimae paschali laudes", "Lauda Sion", "Dies irae"], answer: 0, explain: "Veni Sancte Spiritus (the 'Golden Sequence') belongs to Pentecost; do not confuse it with the hymn Veni Creator Spiritus.", difficulty: 2 },
  { id: "chant-025", topic: "chant", levels: ["ChM"], q: "The Easter sequence Victimae paschali laudes is traditionally attributed to:", choices: ["Notker Balbulus", "Thomas Aquinas", "Hildegard of Bingen", "Wipo of Burgundy"], answer: 3, explain: "Wipo (11th century) is the traditional author; its melody also gave rise to the German Leise 'Christ ist erstanden'.", difficulty: 2 },
  { id: "chant-026", topic: "chant", levels: ["ChM"], q: "Which Marian antiphon is sung during Eastertide?", choices: ["Salve Regina", "Alma Redemptoris Mater", "Regina caeli", "Ave Regina caelorum"], answer: 2, explain: "Regina caeli runs from Easter to Pentecost; Alma covers Advent through the Presentation, Ave Regina caelorum from then through Lent, and Salve Regina the rest of the year.", difficulty: 1 },
  { id: "chant-027", topic: "chant", levels: ["ChM"], q: "Which Marian antiphon is traditionally sung in Advent and through Christmastide?", choices: ["Salve Regina", "Alma Redemptoris Mater", "Regina caeli", "Ave Regina caelorum"], answer: 1, explain: "Alma Redemptoris Mater is used from Advent until the Presentation (February 2).", difficulty: 2 },
  { id: "chant-028", topic: "chant", levels: ["ChM"], q: "The tonus peregrinus is traditionally associated with which psalm?", choices: ["In exitu Israel (Psalm 114)", "Miserere (Psalm 51)", "De profundis (Psalm 130)", "Dixit Dominus (Psalm 110)"], answer: 0, explain: "The 'wandering tone' uses one reciting pitch in the first half-verse and another in the second.", difficulty: 2 },
  { id: "chant-029", topic: "chant", levels: ["ChM"], q: "In a psalm tone, the melodic cadence at the midpoint of each verse is called the:", choices: ["Intonation", "Termination", "Tenor", "Mediant"], answer: 3, explain: "A psalm tone has an intonation, tenor (reciting tone), mediant (mid-verse cadence), and termination (final cadence).", difficulty: 1 },
  { id: "chant-030", topic: "chant", levels: ["ChM"], q: "The abbreviation 'Euouae' in chant books stands for:", choices: ["An instruction to repeat", "The Kyrie eleison", "The vowels of 'saeculorum. Amen'", "A rest of one beat"], answer: 2, explain: "It shows the psalm-tone ending (differentia) to be used, set to the last words of the Gloria Patri.", difficulty: 2 },
  { id: "chant-031", topic: "chant", levels: ["ChM"], q: "Which Benedictine abbey led the 19th-century restoration of Gregorian chant?", choices: ["Cluny", "Solesmes", "Monte Cassino", "St. Gall"], answer: 1, explain: "Solesmes, refounded by Dom Prosper Guéranger, produced the restored editions of Pothier and Mocquereau.", difficulty: 1 },
  { id: "chant-032", topic: "chant", levels: ["ChM"], q: "Pius X's 1903 motu proprio on sacred music, which upheld chant as the model of church music, is titled:", choices: ["Tra le sollecitudini", "Sacrosanctum Concilium", "Musicam sacram", "Docta sanctorum patrum"], answer: 0, explain: "Tra le sollecitudini (1903) promoted chant and Renaissance polyphony; Docta sanctorum (1324) was John XXII's decree against ars nova excesses.", difficulty: 2 },
  { id: "chant-033", topic: "chant", levels: ["ChM"], q: "The long melisma on the final syllable of the Alleluia is called the:", choices: ["Trope", "Neuma", "Clausula", "Jubilus"], answer: 3, explain: "The jubilus was the seed of the sequence, which added text to such melismas.", difficulty: 2 },
  { id: "chant-035", topic: "chant", levels: ["ChM"], q: "Which book contains the chants of the Mass (Ordinary and Proper)?", choices: ["Antiphonale", "Breviary", "Graduale", "Psalter"], answer: 2, explain: "The Graduale holds Mass chants; the Antiphonale holds Office chants.", difficulty: 1 },
  { id: "chant-036", topic: "chant", levels: ["ChM"], q: "The chant tradition of the archdiocese of Milan is called:", choices: ["Mozarabic", "Ambrosian", "Gallican", "Beneventan"], answer: 1, explain: "Ambrosian chant survives in Milan; Mozarabic chant is the old Iberian rite.", difficulty: 1 },
  { id: "chant-039", topic: "chant", levels: ["ChM"], q: "The Exsultet is sung at which service?", choices: ["Easter Vigil", "Good Friday liturgy", "Christmas Midnight Mass", "Ash Wednesday"], answer: 0, explain: "The Exsultet, the Easter proclamation, is sung by a deacon before the paschal candle at the Vigil.", difficulty: 1 },
  { id: "chant-040", topic: "chant", levels: ["ChM"], q: "The Improperia (Reproaches) are sung during:", choices: ["Palm Sunday procession", "Maundy Thursday foot-washing", "The Easter Vigil", "Veneration of the Cross on Good Friday"], answer: 3, explain: "The Reproaches, with the Trisagion refrain, accompany the veneration of the Cross.", difficulty: 2 },

  // ===================== HYMNODY =====================
  { id: "hymn-001", topic: "hymnody", levels: ["ChM"], q: "What syllable count defines Long Meter (LM)?", choices: ["8.6.8.6", "6.6.8.6", "8.8.8.8", "8.7.8.7"], answer: 2, explain: "LM is four lines of eight syllables, as in OLD HUNDREDTH.", difficulty: 1 },
  { id: "hymn-002", topic: "hymnody", levels: ["ChM"], q: "What syllable count defines Common Meter (CM)?", choices: ["8.8.8.8", "8.6.8.6", "6.6.8.6", "7.6.7.6"], answer: 1, explain: "Common Meter, the ballad meter, is used by ST. ANNE and NEW BRITAIN ('Amazing grace').", difficulty: 1 },
  { id: "hymn-003", topic: "hymnody", levels: ["ChM"], q: "What syllable count defines Short Meter (SM)?", choices: ["6.6.8.6", "8.6.8.6", "6.6.6.6", "8.8.6.6"], answer: 0, explain: "SM is 6.6.8.6, as in tunes like ST. THOMAS (Williams) and DENNIS.", difficulty: 1 },
  { id: "hymn-004", topic: "hymnody", levels: ["ChM"], q: "The tune ST. ANNE is attributed to:", choices: ["Henry Purcell", "Thomas Tallis", "Orlando Gibbons", "William Croft"], answer: 3, explain: "Croft's tune is sung to Watts's 'O God, our help in ages past'; Bach's E-flat fugue BWV 552 is nicknamed after it.", difficulty: 1 },
  { id: "hymn-005", topic: "hymnody", levels: ["ChM"], q: "Who wrote the text 'O God, our help in ages past', a paraphrase of Psalm 90?", choices: ["Charles Wesley", "John Newton", "Isaac Watts", "William Cowper"], answer: 2, explain: "Watts's psalm paraphrases (The Psalms of David Imitated, 1719) helped move English worship from metrical psalms to hymns.", difficulty: 1 },
  { id: "hymn-006", topic: "hymnody", levels: ["ChM"], q: "'Joy to the world' by Isaac Watts is a free paraphrase of which psalm?", choices: ["Psalm 23", "Psalm 98", "Psalm 100", "Psalm 150"], answer: 1, explain: "Watts read Psalm 98 christologically; the tune ANTIOCH was arranged by Lowell Mason.", difficulty: 2 },
  { id: "hymn-007", topic: "hymnody", levels: ["ChM"], q: "Which of these texts is by Charles Wesley?", choices: ["Love divine, all loves excelling", "When I survey the wondrous cross", "Rock of ages, cleft for me", "Amazing grace"], answer: 0, explain: "Wesley wrote thousands of hymns; 'When I survey' is Watts, 'Rock of ages' is Toplady, 'Amazing grace' is Newton.", difficulty: 1 },
  { id: "hymn-008", topic: "hymnody", levels: ["ChM"], q: "'Amazing grace' first appeared in which collection?", choices: ["Hymns Ancient and Modern", "Bay Psalm Book", "The English Hymnal", "Olney Hymns"], answer: 3, explain: "Olney Hymns (1779) was a joint project of John Newton and William Cowper.", difficulty: 2 },
  { id: "hymn-009", topic: "hymnody", levels: ["ChM"], q: "The tune OLD HUNDREDTH comes from which source?", choices: ["Luther's Wittenberg hymnal", "The Sarum Antiphoner", "The Genevan Psalter", "Ravenscroft's Psalter"], answer: 2, explain: "It is attributed to Louis Bourgeois and set to Psalm 134 in the 1551 Genevan Psalter; in English it carries Kethe's 'All people that on earth do dwell' (Psalm 100).", difficulty: 2 },
  { id: "hymn-010", topic: "hymnody", levels: ["ChM"], q: "Which composer is most associated with the melodies of the Genevan Psalter?", choices: ["Claude Goudimel", "Louis Bourgeois", "Johann Crüger", "Clément Marot"], answer: 1, explain: "Bourgeois edited many Genevan tunes; Marot and Bèze wrote the French verse; Goudimel later harmonized the psalter.", difficulty: 2 },
  { id: "hymn-011", topic: "hymnody", levels: ["ChM"], q: "Who wrote both text and tune of the chorale 'Ein feste Burg ist unser Gott'?", choices: ["Martin Luther", "Philipp Nicolai", "Paul Gerhardt", "Johann Walter"], answer: 0, explain: "Luther wrote text and melody; Frederic Henry Hedge's 'A mighty fortress is our God' is a widely sung English version.", difficulty: 1 },
  { id: "hymn-012", topic: "hymnody", levels: ["ChM"], q: "Philipp Nicolai wrote text and tune of which pair of chorales (1599)?", choices: ["Nun danket alle Gott and Lobe den Herren", "Ein feste Burg and Vom Himmel hoch", "O Haupt voll Blut und Wunden and Befiehl du deine Wege", "Wachet auf and Wie schön leuchtet der Morgenstern"], answer: 3, explain: "Nicolai's two chorales, the 'king' and 'queen' of chorales, appeared in his Freudenspiegel des ewigen Lebens.", difficulty: 2 },
  { id: "hymn-013", topic: "hymnody", levels: ["ChM"], q: "Who wrote the German text of 'Nun danket alle Gott' ('Now thank we all our God')?", choices: ["Paul Gerhardt", "Joachim Neander", "Martin Rinkart", "Johann Franck"], answer: 2, explain: "Rinkart, a pastor in Eilenburg during the Thirty Years' War, wrote it; the tune NUN DANKET is by Johann Crüger and the English by Catherine Winkworth.", difficulty: 2 },
  { id: "hymn-014", topic: "hymnody", levels: ["ChM"], q: "Which 19th-century translator is best known for English versions of German chorales such as 'Praise to the Lord, the Almighty'?", choices: ["John Mason Neale", "Catherine Winkworth", "Edward Caswall", "Frederick Oakeley"], answer: 1, explain: "Winkworth's Lyra Germanica and Chorale Book for England brought many chorales into English.", difficulty: 1 },
  { id: "hymn-015", topic: "hymnody", levels: ["ChM"], q: "John Mason Neale is best known for translating hymns from which languages?", choices: ["Latin and Greek", "German and Dutch", "Welsh and Gaelic", "French and Italian"], answer: 0, explain: "Neale, an Anglican priest of the Oxford Movement era, translated 'O come, O come, Emmanuel', 'Good King Wenceslas' (original), and many Greek hymns.", difficulty: 1 },
  { id: "hymn-016", topic: "hymnody", levels: ["ChM"], q: "Which translation is by John Mason Neale?", choices: ["Now thank we all our God", "A mighty fortress is our God", "Praise to the Lord, the Almighty", "All glory, laud, and honor"], answer: 3, explain: "Neale translated Theodulph of Orléans's Gloria, laus et honor for Palm Sunday; the others are German chorale translations.", difficulty: 2 },
  { id: "hymn-017", topic: "hymnody", levels: ["ChM"], q: "The Palm Sunday hymn 'All glory, laud, and honor' is usually sung to which tune?", choices: ["LOBE DEN HERREN", "WINCHESTER NEW", "VALET WILL ICH DIR GEBEN", "HYFRYDOL"], answer: 2, explain: "Melchior Teschner's early 17th-century tune is commonly called ST. THEODULPH in English hymnals.", difficulty: 2 },
  { id: "hymn-018", topic: "hymnody", levels: ["ChM"], q: "Who is called the 'father of Latin hymnody'?", choices: ["Gregory the Great", "Ambrose of Milan", "Venantius Fortunatus", "Prudentius"], answer: 1, explain: "Ambrose (4th century) introduced metrical hymns in iambic dimeter (the ancestor of Long Meter) for congregational singing.", difficulty: 1 },
  { id: "hymn-019", topic: "hymnody", levels: ["ChM"], q: "Venantius Fortunatus wrote which pair of Passiontide hymns?", choices: ["Pange lingua gloriosi proelium certaminis and Vexilla regis prodeunt", "Veni Creator Spiritus and Ave maris stella", "Dies irae and Stabat mater", "Adoro te devote and Tantum ergo"], answer: 0, explain: "Fortunatus (6th century) wrote both for the reception of a relic of the True Cross at Poitiers.", difficulty: 2 },
  { id: "hymn-020", topic: "hymnody", levels: ["ChM"], q: "The Corpus Christi hymn 'Pange lingua gloriosi corporis mysterium' is attributed to:", choices: ["Venantius Fortunatus", "Bernard of Clairvaux", "Rabanus Maurus", "Thomas Aquinas"], answer: 3, explain: "Aquinas wrote the Corpus Christi texts; its last two stanzas form the Tantum ergo.", difficulty: 2 },
  { id: "hymn-021", topic: "hymnody", levels: ["ChM"], q: "The hymn 'Veni Creator Spiritus' is traditionally attributed to:", choices: ["Notker Balbulus", "Thomas of Celano", "Rabanus Maurus", "Adam of St. Victor"], answer: 2, explain: "The 9th-century hymn is used at Pentecost, ordinations, and coronations.", difficulty: 2 },
  { id: "hymn-022", topic: "hymnody", levels: ["ChM"], q: "The tune of 'O Sacred Head, sore wounded' was originally a secular song by:", choices: ["Johann Crüger", "Hans Leo Hassler", "Michael Praetorius", "Heinrich Isaac"], answer: 1, explain: "Hassler's love song 'Mein G'müt ist mir verwirret' became HERZLICH TUT MICH VERLANGEN, which Bach used repeatedly in the St. Matthew Passion.", difficulty: 2 },
  { id: "hymn-023", topic: "hymnody", levels: ["ChM"], q: "Who wrote the German text 'O Haupt voll Blut und Wunden'?", choices: ["Paul Gerhardt", "Martin Luther", "Johann Heermann", "Joachim Neander"], answer: 0, explain: "Gerhardt based it on a medieval Latin poem (Salve caput cruentatum) once attributed to Bernard of Clairvaux.", difficulty: 2 },
  { id: "hymn-024", topic: "hymnody", levels: ["ChM"], q: "Who was music editor of The English Hymnal (1906)?", choices: ["Gustav Holst", "Charles Villiers Stanford", "Sydney Nicholson", "Ralph Vaughan Williams"], answer: 3, explain: "Vaughan Williams brought in folk tunes and his own SINE NOMINE and DOWN AMPNEY; Percy Dearmer was general editor.", difficulty: 1 },
  { id: "hymn-025", topic: "hymnody", levels: ["ChM"], q: "Vaughan Williams's tune SINE NOMINE is sung to which text?", choices: ["Come down, O Love divine", "All creatures of our God and King", "For all the saints", "Crown him with many crowns"], answer: 2, explain: "SINE NOMINE sets William Walsham How's All Saints hymn; DOWN AMPNEY sets 'Come down, O Love divine'.", difficulty: 1 },
  { id: "hymn-027", topic: "hymnody", levels: ["ChM"], q: "The first edition of Hymns Ancient and Modern (1861) had which music editor?", choices: ["John Bacchus Dykes", "William Henry Monk", "Samuel Sebastian Wesley", "John Stainer"], answer: 1, explain: "Monk, also composer of EVENTIDE ('Abide with me'), edited the music of this landmark Victorian hymnal.", difficulty: 2 },
  { id: "hymn-028", topic: "hymnody", levels: ["ChM"], q: "The tune NICAEA ('Holy, holy, holy') was composed by:", choices: ["John Bacchus Dykes", "Arthur Sullivan", "Joseph Barnby", "Henry Smart"], answer: 0, explain: "Dykes wrote NICAEA for Reginald Heber's Trinity Sunday text.", difficulty: 1 },
  { id: "hymn-029", topic: "hymnody", levels: ["ChM"], q: "The tune AURELIA ('The Church's one foundation') is by:", choices: ["Samuel Wesley", "Charles Wesley", "John Goss", "Samuel Sebastian Wesley"], answer: 3, explain: "S. S. Wesley, grandson of Charles Wesley, wrote AURELIA; the text is by Samuel John Stone.", difficulty: 2 },
  { id: "hymn-030", topic: "hymnody", levels: ["ChM"], q: "Who wrote the tune CRUCIFER ('Lift high the cross')?", choices: ["Charles Wood", "Martin Shaw", "Sydney Nicholson", "Edward Bairstow"], answer: 2, explain: "Nicholson, founder of the RSCM, wrote CRUCIFER for G. W. Kitchin's text.", difficulty: 2 },
  { id: "hymn-031", topic: "hymnody", levels: ["ChM"], q: "'When in our music God is glorified' (text by Fred Pratt Green) is usually sung to:", choices: ["SLANE", "ENGELBERG", "LASST UNS ERFREUEN", "REPTON"], answer: 1, explain: "Stanford's ENGELBERG is the usual pairing for this hymn about church music.", difficulty: 2 },
  { id: "hymn-032", topic: "hymnody", levels: ["ChM"], q: "Which writer is NOT associated with the late-20th-century English 'hymn explosion'?", choices: ["Isaac Watts", "Brian Wren", "Timothy Dudley-Smith", "Fred Pratt Green"], answer: 0, explain: "The hymn explosion (roughly 1960s-80s) included Wren, Dudley-Smith, Pratt Green, Fred Kaan and Sydney Carter; Watts died in 1748.", difficulty: 1 },
  { id: "hymn-035", topic: "hymnody", levels: ["ChM"], q: "HYFRYDOL ('Alleluia! sing to Jesus') is a Welsh tune by Rowland Prichard in which meter?", choices: ["L.M.", "C.M.D.", "7.6.7.6.D", "8.7.8.7.D"], answer: 3, explain: "HYFRYDOL is 8.7.8.7 doubled, which also suits 'Love divine' and 'Come, thou long-expected Jesus'.", difficulty: 2 },
  { id: "hymn-036", topic: "hymnody", levels: ["ChM"], q: "The Welsh tune CWM RHONDDA is most often sung to:", choices: ["Jesus, lover of my soul", "Love divine, all loves excelling", "Guide me, O thou great Jehovah", "Immortal, invisible, God only wise"], answer: 2, explain: "John Hughes's CWM RHONDDA carries William Williams's text; 'Immortal, invisible' goes to the Welsh tune ST. DENIO.", difficulty: 1 },
  { id: "hymn-037", topic: "hymnody", levels: ["ChM"], q: "'Lift every voice and sing' was written by:", choices: ["Thomas A. Dorsey", "James Weldon Johnson and J. Rosamond Johnson", "Harry T. Burleigh", "Charles Albert Tindley"], answer: 1, explain: "The brothers wrote it in 1900: James the text, J. Rosamond the music.", difficulty: 1 },
  { id: "hymn-038", topic: "hymnody", levels: ["ChM"], q: "Who wrote 'Precious Lord, take my hand' and is often called the father of gospel music?", choices: ["Thomas A. Dorsey", "Charles Albert Tindley", "Andraé Crouch", "Roberta Martin"], answer: 0, explain: "Dorsey wrote it in 1932 after the deaths of his wife and infant son.", difficulty: 1 },
  { id: "hymn-042", topic: "hymnody", levels: ["ChM"], q: "The hymn 'Of the Father's love begotten' uses a text by Prudentius and which tune?", choices: ["VENI EMMANUEL", "PUER NOBIS", "CONDITOR ALME SIDERUM", "DIVINUM MYSTERIUM"], answer: 3, explain: "DIVINUM MYSTERIUM is a medieval melody found in Piae Cantiones (1582).", difficulty: 2 },
  { id: "hymn-043", topic: "hymnody", levels: ["ChM"], q: "'Let all mortal flesh keep silence' (from the Liturgy of St. James) is usually sung to:", choices: ["SLANE", "KINGSFOLD", "PICARDY", "ST. COLUMBA"], answer: 2, explain: "PICARDY is a French carol melody, paired with this text in The English Hymnal (1906).", difficulty: 1 },
  { id: "hymn-049", topic: "hymnody", levels: ["ChM"], q: "LASST UNS ERFREUEN is best known with which English text?", choices: ["Praise to the Lord, the Almighty", "All creatures of our God and King", "Now thank we all our God", "O worship the King"], answer: 1, explain: "William Draper's paraphrase of St. Francis's Canticle of the Sun is set to this 1623 Cologne melody.", difficulty: 1 },

  // ===================== LITURGY =====================
  { id: "lit-001", topic: "liturgy", levels: ["ChM"], q: "Which of these is part of the Ordinary of the Mass?", choices: ["Agnus Dei", "Introit", "Gradual", "Communion"], answer: 0, explain: "The Ordinary is Kyrie, Gloria, Credo, Sanctus/Benedictus, and Agnus Dei; the others are Proper.", difficulty: 1 },
  { id: "lit-002", topic: "liturgy", levels: ["ChM"], q: "In the Western rite, the Gloria in excelsis is traditionally omitted on Sundays during which seasons?", choices: ["Christmas and Epiphany", "Easter and Pentecost", "Lent and Easter", "Advent and Lent"], answer: 3, explain: "The Gloria is omitted in the penitential seasons and returns at Christmas and the Easter Vigil.", difficulty: 1 },
  { id: "lit-003", topic: "liturgy", levels: ["ChM"], q: "On what day does the Western liturgical year begin?", choices: ["January 1", "Christmas Day", "First Sunday of Advent", "Epiphany"], answer: 2, explain: "The church year begins with Advent, four Sundays before Christmas.", difficulty: 1 },
  { id: "lit-004", topic: "liturgy", levels: ["ChM"], q: "Which liturgical color is used at Pentecost?", choices: ["White", "Red", "Green", "Violet"], answer: 1, explain: "Red signifies the fire of the Holy Spirit; it is also used for martyrs.", difficulty: 1 },
  { id: "lit-005", topic: "liturgy", levels: ["ChM"], q: "Rose vestments may be worn on which pair of Sundays?", choices: ["Gaudete (Advent 3) and Laetare (Lent 4)", "Advent 1 and Lent 1", "Palm Sunday and Easter", "Christ the King and Advent 1"], answer: 0, explain: "Both Sundays take their names from the first word of their Introits ('Rejoice').", difficulty: 1 },
  { id: "lit-007", topic: "liturgy", levels: ["ChM"], q: "Western Easter falls on the first Sunday after the ecclesiastical full moon on or after:", choices: ["March 1", "April 1", "March 25", "March 21"], answer: 3, explain: "March 21 is the fixed ecclesiastical equinox; Easter falls between March 22 and April 25.", difficulty: 2 },
  { id: "lit-008", topic: "liturgy", levels: ["ChM"], q: "Ascension Day falls how many days after Easter (counting Easter as day one)?", choices: ["30", "50", "40", "33"], answer: 2, explain: "Ascension is the Thursday forty days after Easter; Pentecost is the fiftieth day.", difficulty: 1 },
  { id: "lit-009", topic: "liturgy", levels: ["ChM"], q: "Trinity Sunday is observed:", choices: ["The Sunday after Ascension", "The Sunday after Pentecost", "The last Sunday before Advent", "The Sunday after Epiphany"], answer: 1, explain: "Trinity Sunday follows Pentecost; Anglican calendars have often counted the following Sundays 'after Trinity'.", difficulty: 1 },
  { id: "lit-010", topic: "liturgy", levels: ["ChM"], q: "On what date is the Presentation of Our Lord (Candlemas) observed?", choices: ["February 2", "January 6", "March 25", "August 6"], answer: 0, explain: "Forty days after Christmas; Jan 6 is Epiphany, Mar 25 the Annunciation, Aug 6 the Transfiguration.", difficulty: 1 },
  { id: "lit-012", topic: "liturgy", levels: ["ChM"], q: "The feast of Christ the King was instituted in 1925 by which pope?", choices: ["Pius X", "Pius XII", "John XXIII", "Pius XI"], answer: 3, explain: "Pius XI instituted it; it is now kept on the last Sunday before Advent.", difficulty: 2 },
  { id: "lit-013", topic: "liturgy", levels: ["ChM"], q: "The first Book of Common Prayer (1549) was chiefly the work of:", choices: ["Thomas Cromwell", "Matthew Parker", "Thomas Cranmer", "Richard Hooker"], answer: 2, explain: "Archbishop Cranmer produced the 1549 and 1552 books under Edward VI.", difficulty: 1 },
  { id: "lit-014", topic: "liturgy", levels: ["ChM"], q: "Which English Prayer Book remained the standard of the Church of England for centuries?", choices: ["1549", "1662", "1552", "1559"], answer: 1, explain: "The 1662 Book of Common Prayer is still the official prayer book of the Church of England.", difficulty: 1 },
  { id: "lit-016", topic: "liturgy", levels: ["ChM"], q: "The Song of Zechariah (Benedictus Dominus Deus Israel) is the gospel canticle traditionally sung at:", choices: ["Lauds / Morning Prayer", "Vespers / Evening Prayer", "Compline", "Terce"], answer: 0, explain: "Lauds: Benedictus; Vespers: Magnificat; Compline: Nunc dimittis.", difficulty: 1 },
  { id: "lit-017", topic: "liturgy", levels: ["ChM"], q: "The Nunc dimittis is the Song of:", choices: ["Mary", "Zechariah", "Moses", "Simeon"], answer: 3, explain: "Simeon's song at the Presentation (Luke 2) is sung at Compline and at Anglican Evensong.", difficulty: 1 },
  { id: "lit-018", topic: "liturgy", levels: ["ChM"], q: "Which psalm is the traditional Venite at Morning Prayer?", choices: ["Psalm 100", "Psalm 23", "Psalm 95", "Psalm 67"], answer: 2, explain: "The Venite is Psalm 95; Psalm 100 is the Jubilate, an alternative invitatory.", difficulty: 1 },
  { id: "lit-019", topic: "liturgy", levels: ["ChM"], q: "In the 1979 Book of Common Prayer, which invitatory is appointed for Morning Prayer in Easter Week?", choices: ["Te Deum", "Christ our Passover (Pascha nostrum)", "Phos hilaron", "Benedicite"], answer: 1, explain: "Pascha nostrum is drawn from 1 Corinthians 5 and Romans 6.", difficulty: 2 },
  { id: "lit-021", topic: "liturgy", levels: ["ChM"], q: "Vatican II's Constitution on the Sacred Liturgy (1963) is known as:", choices: ["Sacrosanctum Concilium", "Lumen gentium", "Musicam sacram", "Gaudium et spes"], answer: 0, explain: "It gave Gregorian chant 'pride of place' and held the pipe organ in high esteem.", difficulty: 1 },
  { id: "lit-022", topic: "liturgy", levels: ["ChM"], q: "In the Revised Common Lectionary, Year A centers on which Gospel?", choices: ["Mark", "Luke", "John", "Matthew"], answer: 3, explain: "Year A: Matthew; Year B: Mark (with John 6); Year C: Luke. John is read in special seasons.", difficulty: 1 },
  { id: "lit-023", topic: "liturgy", levels: ["ChM"], q: "Which days make up the Sacred (Paschal) Triduum?", choices: ["Palm Sunday through Wednesday", "Ash Wednesday through Saturday", "Maundy Thursday evening through Easter Day", "Easter Day through Easter Tuesday"], answer: 2, explain: "The Triduum spans from the Maundy Thursday evening liturgy through Good Friday to the Easter Vigil and Easter Day.", difficulty: 1 },
  { id: "lit-024", topic: "liturgy", levels: ["ChM"], q: "Tenebrae is a service associated with:", choices: ["Advent", "Holy Week", "Pentecost", "All Souls"], answer: 1, explain: "Tenebrae (Matins and Lauds of the last three days of Holy Week) features the gradual extinguishing of candles.", difficulty: 1 },
  { id: "lit-025", topic: "liturgy", levels: ["ChM"], q: "The dialogue 'Lift up your hearts' (Sursum corda) introduces:", choices: ["The Eucharistic Prayer", "The Creed", "The Confession", "The Dismissal"], answer: 0, explain: "The Sursum corda opens the preface, which leads into the Sanctus.", difficulty: 1 },
  { id: "lit-026", topic: "liturgy", levels: ["ChM"], q: "The text of the Sanctus ('Holy, holy, holy') derives chiefly from:", choices: ["Psalm 118", "Luke 2", "Revelation 22", "Isaiah 6"], answer: 3, explain: "The seraphim's song in Isaiah 6; the Benedictus qui venit adds Psalm 118 / Matthew 21.", difficulty: 2 },
  { id: "lit-027", topic: "liturgy", levels: ["ChM"], q: "A single Anglican chant covers one psalm verse in how many bars?", choices: ["Seven", "Twelve", "Ten", "Twenty"], answer: 2, explain: "A single chant has 10 bars (4 + 6, split at the mediant); a double chant covers two verses in 20 bars.", difficulty: 2 },
  { id: "lit-028", topic: "liturgy", levels: ["ChM"], q: "The psalter text printed in Prayer Books from 1549 through 1662 is the translation of:", choices: ["William Tyndale", "Miles Coverdale", "The King James translators", "Thomas Sternhold"], answer: 1, explain: "Coverdale's psalter, from the Great Bible, remained in the 1662 BCP even after the King James Bible appeared.", difficulty: 2 },
  { id: "lit-029", topic: "liturgy", levels: ["ChM"], q: "Which canonical hour is traditionally prayed around midday?", choices: ["Sext", "Terce", "None", "Prime"], answer: 0, explain: "Terce, Sext and None fall at the third, sixth and ninth hours (about 9 a.m., noon, and 3 p.m.).", difficulty: 1 },
  { id: "lit-030", topic: "liturgy", levels: ["ChM"], q: "Anglican Evensong combines elements of which two monastic offices?", choices: ["Matins and Lauds", "Lauds and Prime", "None and Vespers", "Vespers and Compline"], answer: 3, explain: "Cranmer's Evening Prayer drew on Vespers (Magnificat) and Compline (Nunc dimittis); Morning Prayer drew on Matins and Lauds.", difficulty: 1 },
  { id: "lit-031", topic: "liturgy", levels: ["ChM"], q: "The 'O Antiphons' are sung with the Magnificat during which days?", choices: ["December 24-31", "The first week of Advent", "December 17-23", "The Octave of Epiphany"], answer: 2, explain: "The seven O Antiphons are paraphrased in 'O come, O come, Emmanuel'.", difficulty: 2 },
  { id: "lit-032", topic: "liturgy", levels: ["ChM"], q: "Luther's German-language order of Mass of 1526 is called the:", choices: ["Formula missae", "Deutsche Messe", "Augsburg Confession", "Kirchenordnung"], answer: 1, explain: "The Formula missae (1523) was his earlier, largely Latin revision.", difficulty: 2 },
  { id: "lit-033", topic: "liturgy", levels: ["ChM"], q: "The Festival of Nine Lessons and Carols in its familiar form was introduced at King's College, Cambridge, in:", choices: ["1918", "1880", "1928", "1945"], answer: 0, explain: "Eric Milner-White adapted it from E. W. Benson's 1880 service at Truro.", difficulty: 2 },
  { id: "lit-036", topic: "liturgy", levels: ["ChM"], q: "In a traditional Requiem Mass, which sequence is sung?", choices: ["Stabat mater", "Lauda Sion", "Victimae paschali laudes", "Dies irae"], answer: 3, explain: "The Dies irae was retained for Masses for the dead; Fauré and Duruflé set only its final Pie Jesu portion.", difficulty: 1 },

  // ===================== CHOIR =====================
  { id: "choir-001", topic: "choir", levels: ["ChM"], q: "The Royal School of Church Music was founded in 1927 (as the School of English Church Music) by:", choices: ["Walford Davies", "Edward Bairstow", "Sydney Nicholson", "Charles Wood"], answer: 2, explain: "Nicholson left his post as organist of Westminster Abbey to found it.", difficulty: 1 },
  { id: "choir-002", topic: "choir", levels: ["ChM"], q: "The term 'passaggio' refers to:", choices: ["A fast melismatic run", "A transition area between vocal registers", "A sustained crescendo on one note", "Breath taken between phrases"], answer: 1, explain: "Singers learn to negotiate the passaggi smoothly to avoid audible register breaks.", difficulty: 1 },
  { id: "choir-003", topic: "choir", levels: ["ChM"], q: "A crescendo and decrescendo on a single sustained note is called:", choices: ["Messa di voce", "Portamento", "Sostenuto", "Coloratura"], answer: 0, explain: "Messa di voce is a classic exercise in breath and registration control.", difficulty: 1 },
  { id: "choir-004", topic: "choir", levels: ["ChM"], q: "When singing a diphthong such as in 'night', the singer should generally:", choices: ["Sustain the second vowel throughout", "Divide the note evenly between both vowels", "Avoid the first vowel entirely", "Sustain the first vowel and move to the second late"], answer: 3, explain: "The primary vowel [a] carries the tone; the vanishing [i] arrives just before the next consonant.", difficulty: 1 },
  { id: "choir-005", topic: "choir", levels: ["ChM"], q: "What does the diaphragm do during inhalation?", choices: ["It relaxes and rises", "It closes the glottis", "It contracts and descends", "It raises the larynx"], answer: 2, explain: "The diaphragm flattens downward as it contracts, expanding the chest cavity.", difficulty: 1 },
  { id: "choir-006", topic: "choir", levels: ["ChM"], q: "The typical rate of classical vocal vibrato is about:", choices: ["1-2 cycles per second", "5-7 cycles per second", "12-15 cycles per second", "20-30 cycles per second"], answer: 1, explain: "A rate much slower reads as a wobble; much faster as a bleat or tremolo.", difficulty: 2 },
  { id: "choir-007", topic: "choir", levels: ["ChM"], q: "The 'singer's formant', which lets trained voices carry over an orchestra, is a resonance peak near:", choices: ["2.5-3 kHz", "250-500 Hz", "800-1000 Hz", "8-10 kHz"], answer: 0, explain: "It arises from clustering of higher formants (F3-F5) and lies where orchestral energy is relatively weak.", difficulty: 3 },
  { id: "choir-008", topic: "choir", levels: ["ChM"], q: "Which vowel has the highest second formant (F2)?", choices: ["[u] as in 'boot'", "[o] as in 'go'", "[a] as in 'father'", "[i] as in 'see'"], answer: 3, explain: "[i] combines a low F1 with a very high F2; back rounded vowels have low F2.", difficulty: 3 },
  { id: "choir-009", topic: "choir", levels: ["ChM"], q: "For young children's choirs, most pedagogues recommend building the voice from:", choices: ["The low chest voice, extended upward", "Loud belting to build stamina", "The light head voice, often using descending patterns", "Spoken chant only"], answer: 2, explain: "Descending exercises carry the light head-voice quality into the lower range and prevent pushing.", difficulty: 1 },
  { id: "choir-010", topic: "choir", levels: ["ChM"], q: "The 'cambiata' concept in choral music education addresses:", choices: ["Falsetto singing in countertenors", "Adolescent boys' changing voices", "Breath management in older singers", "Latin pronunciation"], answer: 1, explain: "Irvin Cooper's cambiata approach writes limited-range parts for boys in the voice change.", difficulty: 2 },
  { id: "choir-011", topic: "choir", levels: ["ChM"], q: "The hand signs widely used in Kodály-based sight-singing were developed by:", choices: ["John Curwen", "Émile Jaques-Dalcroze", "Carl Orff", "Lowell Mason"], answer: 0, explain: "Curwen created them for his Tonic Sol-fa system; Kodály adopted them.", difficulty: 2 },
  { id: "choir-012", topic: "choir", levels: ["ChM"], q: "Eurhythmics, which teaches rhythm through bodily movement, was developed by:", choices: ["Zoltán Kodály", "Shinichi Suzuki", "Carl Orff", "Émile Jaques-Dalcroze"], answer: 3, explain: "Dalcroze, a Swiss musician, developed it in the early 20th century.", difficulty: 1 },
  { id: "choir-013", topic: "choir", levels: ["ChM"], q: "A 'balanced' vocal onset is one in which:", choices: ["The glottis closes firmly before breath is released", "Air flows audibly before the tone begins", "Breath flow and vocal-fold closure begin together", "The tone starts below pitch and slides up"], answer: 2, explain: "The other two classic onsets are the glottal (hard) and the breathy (aspirate).", difficulty: 2 },
  { id: "choir-014", topic: "choir", levels: ["ChM"], q: "The RSCM's graded training scheme for choristers is called:", choices: ["Singing Success", "Voice for Life", "Chorister Pathway", "Sing Up"], answer: 1, explain: "Voice for Life replaced the older RSCM chorister award scheme.", difficulty: 2 },
  { id: "choir-015", topic: "choir", levels: ["ChM"], q: "The German system of classifying voices by type and weight (e.g., lyric soprano) is called the:", choices: ["Fach system", "Stimmbildung", "Tessitura", "Ambitus"], answer: 0, explain: "Fach classifications are used especially in opera casting.", difficulty: 2 },

  // ===================== CHORAL REPERTOIRE =====================
  { id: "crep-001", topic: "choral-rep", levels: ["ChM"], q: "Tallis's Spem in alium is written for how many voices?", choices: ["24", "32", "48", "40"], answer: 3, explain: "Forty independent parts, arranged as eight choirs of five voices.", difficulty: 1 },
  { id: "crep-002", topic: "choral-rep", levels: ["ChM"], q: "William Byrd wrote Latin Masses for which voice counts?", choices: ["Four, six, and eight", "Five only", "Three, four, and five", "Four and eight"], answer: 2, explain: "Byrd, a Catholic under Elizabeth I, published them discreetly in the 1590s.", difficulty: 2 },
  { id: "crep-003", topic: "choral-rep", levels: ["ChM"], q: "A verse anthem, such as Gibbons's 'This is the record of John', is characterized by:", choices: ["Unaccompanied full choir throughout", "Solo passages with accompaniment alternating with full choir", "Double choir antiphony", "A chorale melody in the tenor"], answer: 1, explain: "A 'full anthem' (e.g., Gibbons's 'Hosanna to the Son of David') is for choir throughout.", difficulty: 1 },
  { id: "crep-004", topic: "choral-rep", levels: ["ChM"], q: "Purcell's 'Rejoice in the Lord alway' is nicknamed the:", choices: ["Bell Anthem", "Funeral Anthem", "Coronation Anthem", "Chapel Royal Anthem"], answer: 0, explain: "Its string introduction imitates descending peals of bells.", difficulty: 2 },
  { id: "crep-005", topic: "choral-rep", levels: ["ChM"], q: "Handel's 'Zadok the Priest' was written for the coronation of:", choices: ["George I", "George III", "Queen Anne", "George II"], answer: 3, explain: "It is one of four anthems for George II's coronation in 1727, and has been sung at every British coronation since.", difficulty: 1 },
  { id: "crep-006", topic: "choral-rep", levels: ["ChM"], q: "Handel's Messiah received its premiere in 1742 in:", choices: ["London", "Oxford", "Dublin", "Hamburg"], answer: 2, explain: "It premiered at the New Music Hall on Fishamble Street, Dublin.", difficulty: 1 },
  { id: "crep-007", topic: "choral-rep", levels: ["ChM"], q: "Who completed Mozart's Requiem after his death?", choices: ["Antonio Salieri", "Franz Xaver Süssmayr", "Joseph Eybler", "Michael Haydn"], answer: 1, explain: "Eybler began the task, but Süssmayr's completion became the standard version.", difficulty: 1 },
  { id: "crep-008", topic: "choral-rep", levels: ["ChM"], q: "Brahms's Ein deutsches Requiem differs from the Latin Requiem in that it:", choices: ["Sets German biblical texts chosen by Brahms", "Sets the Latin Mass in German translation", "Was written for liturgical use", "Uses only chorales"], answer: 0, explain: "Brahms compiled texts from Luther's Bible, focusing on comfort for the living.", difficulty: 1 },
  { id: "crep-009", topic: "choral-rep", levels: ["ChM"], q: "Fauré's Requiem notably omits most of the Dies irae but includes:", choices: ["Tuba mirum", "Rex tremendae", "Lacrimosa", "In paradisum"], answer: 3, explain: "Fauré set only the Pie Jesu from the sequence and added the Libera me and In paradisum.", difficulty: 1 },
  { id: "crep-010", topic: "choral-rep", levels: ["ChM", "AAGO"], q: "Duruflé's Requiem, Op. 9 is built largely on:", choices: ["Lutheran chorales", "Original folk-like tunes", "Gregorian chant melodies from the Mass for the Dead", "Twelve-tone rows"], answer: 2, explain: "Duruflé wove the chants of the Requiem Mass through each movement.", difficulty: 1 },
  { id: "crep-011", topic: "choral-rep", levels: ["ChM"], q: "Mendelssohn's Elijah was first performed in 1846 at:", choices: ["Leipzig", "Birmingham", "Düsseldorf", "London"], answer: 1, explain: "It premiered at the Birmingham Festival in an English translation.", difficulty: 2 },
  { id: "crep-012", topic: "choral-rep", levels: ["ChM"], q: "Elgar's The Dream of Gerontius sets a poem by:", choices: ["John Henry Newman", "Alfred Tennyson", "Gerard Manley Hopkins", "Christina Rossetti"], answer: 0, explain: "Newman's poem follows a soul's journey after death; it premiered in Birmingham in 1900.", difficulty: 1 },
  { id: "crep-013", topic: "choral-rep", levels: ["ChM"], q: "Parry's 'I was glad' was written for the coronation of:", choices: ["George V", "Victoria", "George VI", "Edward VII"], answer: 3, explain: "It was composed for 1902 and revised for George V's coronation in 1911.", difficulty: 2 },
  { id: "crep-014", topic: "choral-rep", levels: ["ChM"], q: "Herbert Howells's Collegium Regale service was written for:", choices: ["St. John's College, Cambridge", "Westminster Abbey", "King's College, Cambridge", "St. Paul's Cathedral"], answer: 2, explain: "The title means 'Royal College', i.e., King's.", difficulty: 1 },
  { id: "crep-015", topic: "choral-rep", levels: ["ChM"], q: "Howells's Hymnus Paradisi was a response to:", choices: ["The coronation of Elizabeth II", "The death of his son Michael", "World War I", "The death of Vaughan Williams"], answer: 1, explain: "Michael Howells died suddenly in 1935 at age nine; the work was released for performance only in 1950.", difficulty: 2 },
  { id: "crep-016", topic: "choral-rep", levels: ["ChM"], q: "Britten's A Ceremony of Carols is scored for treble voices and:", choices: ["Harp", "Organ", "String quartet", "Piano"], answer: 0, explain: "Britten wrote it in 1942 during his sea voyage back to England.", difficulty: 1 },
  { id: "crep-017", topic: "choral-rep", levels: ["ChM"], q: "Britten's festival cantata Rejoice in the Lamb sets text by:", choices: ["W. H. Auden", "George Herbert", "John Donne", "Christopher Smart"], answer: 3, explain: "It uses Smart's Jubilate Agno, including the passage about his cat Jeoffry.", difficulty: 2 },
  { id: "crep-018", topic: "choral-rep", levels: ["ChM"], q: "Vaughan Williams's Five Mystical Songs set poems by:", choices: ["John Donne", "Henry Vaughan", "George Herbert", "Thomas Traherne"], answer: 2, explain: "They set Herbert's poems for baritone, chorus, and orchestra (1911).", difficulty: 1 },
  { id: "crep-019", topic: "choral-rep", levels: ["ChM"], q: "Rachmaninoff's All-Night Vigil is his opus:", choices: ["18", "37", "30", "45"], answer: 1, explain: "Op. 37 (1915) for unaccompanied choir sets texts of the Russian Orthodox vigil.", difficulty: 2 },
  { id: "crep-020", topic: "choral-rep", levels: ["ChM"], q: "Bernstein's Chichester Psalms sets the psalm texts in:", choices: ["Hebrew", "Latin", "English", "Aramaic"], answer: 0, explain: "It was commissioned for Chichester Cathedral's 1965 festival.", difficulty: 1 },
  { id: "crep-021", topic: "choral-rep", levels: ["ChM"], q: "Stravinsky's Symphony of Psalms was commissioned for the 50th anniversary of:", choices: ["The New York Philharmonic", "The Chicago Symphony", "The Philadelphia Orchestra", "The Boston Symphony Orchestra"], answer: 3, explain: "Koussevitzky commissioned it; it omits violins and violas.", difficulty: 2 },
  { id: "crep-022", topic: "choral-rep", levels: ["ChM"], q: "Randall Thompson's Alleluia was written for the opening of:", choices: ["Lincoln Center", "Harvard's Memorial Church", "Tanglewood (Berkshire Music Center)", "Riverside Church"], answer: 2, explain: "Koussevitzky asked for a fanfare in 1940; Thompson delivered a quiet, reflective Alleluia.", difficulty: 2 },
  { id: "crep-023", topic: "choral-rep", levels: ["ChM"], q: "William L. Dawson, known for spiritual arrangements, led the choir of:", choices: ["Fisk University", "Tuskegee Institute", "Howard University", "Hampton Institute"], answer: 1, explain: "Dawson directed the Tuskegee Institute Choir from 1931 to 1955.", difficulty: 2 },
  { id: "crep-024", topic: "choral-rep", levels: ["ChM"], q: "Arvo Pärt's compositional style based on triads and stepwise lines is called:", choices: ["Tintinnabuli", "Minimalism of process", "Spectralism", "Holy minimalism of phase"], answer: 0, explain: "Pärt developed tintinnabuli ('little bells') in the mid-1970s.", difficulty: 1 },
  { id: "crep-026", topic: "choral-rep", levels: ["ChM"], q: "Heinrich Schütz studied in Venice with:", choices: ["Claudio Monteverdi", "Adrian Willaert", "Andrea Gabrieli", "Giovanni Gabrieli"], answer: 3, explain: "Schütz studied with Giovanni Gabrieli (1609-12) and brought the polychoral style to Germany.", difficulty: 2 },
  { id: "crep-027", topic: "choral-rep", levels: ["ChM"], q: "Allegri's Miserere, long guarded by the Sistine Chapel, sets which psalm?", choices: ["Psalm 130", "Psalm 42", "Psalm 51", "Psalm 22"], answer: 2, explain: "The young Mozart reportedly wrote it down from memory after hearing it in 1770.", difficulty: 1 },
  { id: "crep-029", topic: "choral-rep", levels: ["ChM"], q: "Which Mass is linked by legend to Palestrina's 'saving' of polyphony at the Council of Trent?", choices: ["Missa Pange lingua", "Missa Papae Marcelli", "Missa L'homme armé", "Missa Assumpta est Maria"], answer: 1, explain: "The story is largely legend, but the Mass's clear text-setting matched Trent's concerns.", difficulty: 1 },
  { id: "crep-031", topic: "choral-rep", levels: ["ChM"], q: "Which Poulenc work for Lent is for unaccompanied choir?", choices: ["Quatre motets pour un temps de pénitence", "Gloria", "Stabat mater", "Litanies à la Vierge noire"], answer: 0, explain: "The Gloria and Stabat mater use orchestra; the Litanies use organ.", difficulty: 2 },
  { id: "crep-034", topic: "choral-rep", levels: ["ChM"], q: "Vaughan Williams's Mass in G minor is scored for:", choices: ["Choir and orchestra", "Choir and organ", "Treble voices and harp", "Unaccompanied double choir with soloists"], answer: 3, explain: "Completed in 1921-22, it revived the a cappella Tudor Mass tradition.", difficulty: 2 },
  { id: "crep-035", topic: "choral-rep", levels: ["ChM"], q: "Which composer, Irish-born, taught Vaughan Williams, Holst, and Howells at the Royal College of Music?", choices: ["Hubert Parry", "Edward Elgar", "Charles Villiers Stanford", "Charles Wood"], answer: 2, explain: "Stanford's Services in B-flat, C, and G remain cathedral staples.", difficulty: 1 },

  // ===================== ORGAN HISTORY =====================
  { id: "ohist-001", topic: "organ-history", levels: ["CAGO", "AAGO"], q: "The hydraulis, the earliest known organ, is credited to:", choices: ["Archimedes", "Ctesibius of Alexandria", "Vitruvius", "Hero of Byzantium"], answer: 1, explain: "Ctesibius (3rd century BCE) used water pressure to stabilize the wind supply.", difficulty: 1 },
  { id: "ohist-002", topic: "organ-history", levels: ["AAGO"], q: "Arp Schnitger is the leading builder of which tradition?", choices: ["North German Baroque", "French Classical", "Italian Renaissance", "English Victorian"], answer: 0, explain: "Schnitger (1648-1719) built St. Jacobi, Hamburg, among many others in north Germany and the Netherlands.", difficulty: 1 },
  { id: "ohist-003", topic: "organ-history", levels: ["AAGO"], q: "Gottfried Silbermann worked chiefly in:", choices: ["Alsace", "Holland", "Bavaria", "Saxony"], answer: 3, explain: "His organs include Freiberg Cathedral; his brother Andreas worked in Strasbourg (Alsace).", difficulty: 1 },
  { id: "ohist-005", topic: "organ-history", levels: ["AAGO"], q: "François-Henri Clicquot is a major builder of the:", choices: ["French Romantic organ", "English cathedral organ", "French Classical organ", "Spanish Baroque organ"], answer: 2, explain: "Clicquot's work includes Poitiers Cathedral; Cavaillé-Coll later rebuilt his Saint-Sulpice organ.", difficulty: 1 },
  { id: "ohist-006", topic: "organ-history", levels: ["AAGO"], q: "L'art du facteur d'orgues, the great 18th-century treatise on organ building, was written by:", choices: ["Marin Mersenne", "Dom Bédos de Celles", "Michael Praetorius", "Andreas Werckmeister"], answer: 1, explain: "Bédos's richly illustrated treatise appeared in parts from 1766 to 1778.", difficulty: 2 },
  { id: "ohist-007", topic: "organ-history", levels: ["AAGO"], q: "Which Paris organ by Cavaillé-Coll (1841) was among the first to use the Barker lever?", choices: ["Saint-Denis", "Saint-Sulpice", "Notre-Dame", "Sainte-Clotilde"], answer: 0, explain: "Saint-Denis was Cavaillé-Coll's first major instrument.", difficulty: 2 },
  { id: "ohist-008", topic: "organ-history", levels: ["AAGO"], q: "The Barker lever is:", choices: ["An electric stop control", "A swell-box mechanism", "A tuning device for reeds", "A pneumatic assist that lightens heavy mechanical key actions"], answer: 3, explain: "Charles Spackman Barker's device let large coupled organs be played without excessive key weight.", difficulty: 1 },
  { id: "ohist-009", topic: "organ-history", levels: ["AAGO"], q: "Cavaillé-Coll's 'pédales de combinaison' (ventils) let the organist:", choices: ["Change the tuning temperament", "Open the shutters of the swell box", "Bring on or cancel prepared groups of stops by admitting wind to chests", "Couple manuals at the octave only"], answer: 2, explain: "Stops could be drawn in advance and their wind supply released by pedal, e.g., the reeds (anches).", difficulty: 2 },
  { id: "ohist-010", topic: "organ-history", levels: ["AAGO"], q: "Henry 'Father' Willis built the organ at St. George's Hall, Liverpool (1855). He was:", choices: ["French", "English", "German", "American"], answer: 1, explain: "Willis was the leading Victorian English builder; his work includes St. Paul's Cathedral.", difficulty: 1 },
  { id: "ohist-011", topic: "organ-history", levels: ["AAGO"], q: "G. Donald Harrison is associated with which organ style?", choices: ["The American Classic organ", "The Orgelbewegung", "The theatre organ", "The French Romantic organ"], answer: 0, explain: "Harrison, English-born, joined Skinner in 1927 and shaped Aeolian-Skinner's eclectic 'American Classic' ideal.", difficulty: 2 },
  { id: "ohist-012", topic: "organ-history", levels: ["AAGO"], q: "Ernest M. Skinner is associated with which windchest design?", choices: ["The slider chest", "The spring chest", "The cone chest", "The pitman chest"], answer: 3, explain: "Skinner's electro-pneumatic pitman chest gave fast, reliable response for orchestral-style organs.", difficulty: 2 },
  { id: "ohist-013", topic: "organ-history", levels: ["AAGO"], q: "Walter Holtkamp Sr. of Cleveland was known for:", choices: ["Theatre-organ unification", "Highly enclosed orchestral organs", "Exposed, unencased pipework with clear choruses", "Reed organs for parlors"], answer: 2, explain: "Holtkamp was an American pioneer of organ reform ideals in the 1930s.", difficulty: 2 },
  { id: "ohist-014", topic: "organ-history", levels: ["AAGO"], q: "Before founding his firm, Charles Fisk had worked as a:", choices: ["Concert pianist", "Physicist on the Manhattan Project", "Church architect", "Piano technician"], answer: 1, explain: "Fisk left physics for organ building and became a leader of the American tracker revival.", difficulty: 2 },
  { id: "ohist-015", topic: "organ-history", levels: ["AAGO"], q: "The 1958 Flentrop organ at Harvard's Busch-Reisinger Museum (now Busch Hall) is closely associated with:", choices: ["E. Power Biggs", "Virgil Fox", "Albert Schweitzer", "Marcel Dupré"], answer: 0, explain: "Biggs's broadcasts and recordings on it helped spread the tracker revival in America.", difficulty: 2 },
  { id: "ohist-016", topic: "organ-history", levels: ["AAGO"], q: "Flentrop is an organ firm from:", choices: ["Germany", "Denmark", "Switzerland", "The Netherlands"], answer: 3, explain: "Flentrop Orgelbouw is based in Zaandam.", difficulty: 1 },
  { id: "ohist-017", topic: "organ-history", levels: ["AAGO"], q: "Rudolf von Beckerath's 1956 organ at Trinity Lutheran Church in Cleveland was significant as:", choices: ["The largest theatre organ ever built", "The first electric-action organ", "An early modern mechanical-action organ in America", "The first organ in equal temperament"], answer: 2, explain: "Beckerath (Hamburg) was a leading Orgelbewegung builder.", difficulty: 3 },
  { id: "ohist-018", topic: "organ-history", levels: ["AAGO"], q: "The Orgelbewegung (Organ Reform Movement) sought to:", choices: ["Make the organ imitate the orchestra", "Return to Baroque principles of tone and mechanical action", "Replace pipes with electronic tone", "Increase wind pressures dramatically"], answer: 1, explain: "It grew in 1920s Germany, inspired partly by Schweitzer's writings.", difficulty: 1 },
  { id: "ohist-020", topic: "organ-history", levels: ["AAGO"], q: "Volume II of Michael Praetorius's Syntagma musicum (1619), a key source on early organs, is titled:", choices: ["De Organographia", "Musica poetica", "Harmonie universelle", "Orgelprobe"], answer: 0, explain: "It describes and illustrates instruments of the time.", difficulty: 2 },
  { id: "ohist-021", topic: "organ-history", levels: ["CAGO", "AAGO"], q: "Horizontal reeds projecting from the case, typical of Iberian organs, are called:", choices: ["En taille", "Positif de dos", "Bombarde", "En chamade"], answer: 3, explain: "Trumpets en chamade are a hallmark of Spanish and Portuguese organs.", difficulty: 1 },
  { id: "ohist-022", topic: "organ-history", levels: ["AAGO"], q: "A characteristic of the Iberian Baroque organ is:", choices: ["Large independent pedal divisions", "Enclosed swell divisions", "Divided (split) keyboards with separate bass and treble stops", "Multiple manuals of equal size"], answer: 2, explain: "Medio registro (split registers) allowed solo and accompaniment on one manual.", difficulty: 2 },
  { id: "ohist-023", topic: "organ-history", levels: ["AAGO"], q: "In the Italian Ripieno, a rank labeled 'Decimanona' sounds at which pitch (on an 8' basis)?", choices: ["2'", "1 1/3'", "2 2/3'", "1'"], answer: 1, explain: "Decimanona = 19th; Ottava = 4', Decimaquinta = 2', Vigesimaseconda = 1'.", difficulty: 2 },
  { id: "ohist-024", topic: "organ-history", levels: ["AAGO"], q: "The first swell box (the 'nag's head swell') is credited to Abraham Jordan in 1712 in:", choices: ["London", "Paris", "Hamburg", "Boston"], answer: 0, explain: "Jordan installed it at St. Magnus the Martyr; the swell became characteristic of English organs.", difficulty: 3 },
  { id: "ohist-025", topic: "organ-history", levels: ["AAGO"], q: "Robert Hope-Jones's 'unit orchestra' principle was developed further by which company?", choices: ["Aeolian-Skinner", "Casavant", "Hook & Hastings", "Wurlitzer"], answer: 3, explain: "Unification (one rank playable at multiple pitches) defined the theatre organ.", difficulty: 2 },
  { id: "ohist-026", topic: "organ-history", levels: ["AAGO"], q: "Casavant Frères is based in:", choices: ["Boston, Massachusetts", "Erie, Pennsylvania", "Saint-Hyacinthe, Quebec", "Hagerstown, Maryland"], answer: 2, explain: "Casavant, founded in 1879, is Canada's best-known builder.", difficulty: 1 },
  { id: "ohist-027", topic: "organ-history", levels: ["AAGO"], q: "E. & G. G. Hook, builders of the 1864 organ in Mechanics Hall, Worcester, were based in:", choices: ["New York", "Boston", "Philadelphia", "Chicago"], answer: 1, explain: "The Hook brothers' firm later became Hook & Hastings.", difficulty: 2 },
  { id: "ohist-028", topic: "organ-history", levels: ["AAGO"], q: "David Tannenberg was an 18th-century builder associated with:", choices: ["The Moravian communities of Pennsylvania", "Spanish missions in California", "The Shakers of New England", "The Anglican churches of Virginia"], answer: 0, explain: "Tannenberg, working from Lititz, PA, was the leading organ builder of colonial America.", difficulty: 2 },
  { id: "ohist-029", topic: "organ-history", levels: ["CAGO", "AAGO"], q: "In a slider chest, each key controls:", choices: ["One individual pipe only", "One complete stop", "The wind pressure of the whole organ", "A channel shared by all pipes of that note"], answer: 3, explain: "Sliders, moved by the stop knobs, determine which pipes on the channel receive wind.", difficulty: 2 },
  { id: "ohist-030", topic: "organ-history", levels: ["CAGO", "AAGO"], q: "Organ wind pressure is traditionally measured in:", choices: ["Pounds per square foot", "Decibels", "Inches (or millimeters) of water column", "Cubic feet per minute"], answer: 2, explain: "A water-filled U-tube manometer (wind gauge) shows pressure as the height difference in the water.", difficulty: 1 },
  { id: "ohist-031", topic: "organ-history", levels: ["AAGO"], q: "The medieval 'Blockwerk' was:", choices: ["A carved organ case", "An undivided chorus of many ranks without separate stop controls", "A type of reed stop", "A keyboard of pedal keys"], answer: 1, explain: "Separating the Blockwerk into individual stops came later; the Hintersatz descends from it.", difficulty: 2 },
  { id: "ohist-033", topic: "organ-history", levels: ["AAGO"], q: "Albert Schweitzer's 1906 essay that helped inspire the Orgelbewegung compared organ building in:", choices: ["Germany and France", "England and America", "Italy and Spain", "Holland and Denmark"], answer: 0, explain: "Deutsche und französische Orgelbaukunst praised Silbermann and Cavaillé-Coll over factory-made organs.", difficulty: 2 },

  // ===================== REGISTRATION =====================
  { id: "reg-001", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Nazard 2 2/3' sounds at what interval above 8' pitch?", choices: ["Fifth", "Seventeenth", "Nineteenth", "Twelfth (octave plus fifth)"], answer: 3, explain: "2 2/3' is the third harmonic of 8'.", difficulty: 1 },
  { id: "reg-002", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Tierce 1 3/5' sounds which harmonic of 8' pitch?", choices: ["3rd", "6th", "5th", "7th"], answer: 2, explain: "8 ÷ 5 = 1 3/5; it sounds two octaves and a major third above (the 17th).", difficulty: 2 },
  { id: "reg-003", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Larigot sounds at which pitch?", choices: ["1 3/5'", "1 1/3'", "2 2/3'", "1 1/7'"], answer: 1, explain: "The Larigot (19th) is the 6th harmonic, an octave above the Nazard.", difficulty: 2 },
  { id: "reg-004", topic: "registration", levels: ["AAGO"], q: "A Septième 1 1/7' sounds which harmonic of 8' pitch?", choices: ["7th", "5th", "6th", "9th"], answer: 0, explain: "8 ÷ 7 = 1 1/7; the 7th harmonic is noticeably flat of an equal-tempered minor seventh.", difficulty: 3 },
  { id: "reg-005", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Sesquialtera combines which two ranks?", choices: ["4' and 2'", "2' and 1 1/3'", "8' and 2 2/3'", "2 2/3' and 1 3/5'"], answer: 3, explain: "Its name ('one and a half') refers to the 3:2 ratio of the fifth.", difficulty: 1 },
  { id: "reg-006", topic: "registration", levels: ["CAGO", "AAGO"], q: "The classic five-rank Cornet comprises:", choices: ["8', 4', 2', 1', 1/2'", "16', 8', 4', 2', 1'", "8', 4', 2 2/3', 2', 1 3/5'", "4', 2 2/3', 2', 1 1/3', 1'"], answer: 2, explain: "It sounds harmonics 1-5 and is often a treble-only mounted stop.", difficulty: 1 },
  { id: "reg-007", topic: "registration", levels: ["AAGO"], q: "In French Classical practice, the Plein jeu is built on:", choices: ["Trumpets, clairons, and cornets", "Principal chorus with Fourniture and Cymbale", "Flutes and mutations including the Tierce", "Strings and celestes"], answer: 1, explain: "The Plein jeu is the principal chorus with mixtures; reeds and tierces are excluded.", difficulty: 1 },
  { id: "reg-008", topic: "registration", levels: ["AAGO"], q: "The French Classical Grand jeu typically includes:", choices: ["Trompette, Clairon, Cornet, and Prestant, without mixtures", "Montres with Fourniture and Cymbale", "Bourdon 8' and Flûte 4' with tremulant", "All stops of the organ"], answer: 0, explain: "The Grand jeu combines reeds and cornets; mixtures belong to the Plein jeu.", difficulty: 2 },
  { id: "reg-009", topic: "registration", levels: ["AAGO"], q: "In a Tierce en taille, the solo line lies in:", choices: ["The soprano, played by the right hand", "The pedal, as a cantus firmus", "Both hands in octaves", "The tenor range, played by the left hand"], answer: 3, explain: "'Taille' means tenor; the solo is a Positif tierce combination accompanied by soft 8' foundations.", difficulty: 2 },
  { id: "reg-010", topic: "registration", levels: ["AAGO"], q: "A traditional French Classical registration for the Voix humaine adds:", choices: ["Plein jeu and Cymbale", "Trompette and Clairon", "Bourdon 8', Flûte 4', and tremulant", "Nazard and Tierce only"], answer: 2, explain: "The flues round out the short-resonator reed's thin tone.", difficulty: 2 },
  { id: "reg-011", topic: "registration", levels: ["AAGO"], q: "In French Romantic registration, 'Fonds' means:", choices: ["Reeds and mixtures", "Foundation stops of 8' and 4' (principals, flutes, strings)", "Only the pedal stops", "The full organ"], answer: 1, explain: "'Fonds' is contrasted with 'Anches' (reeds, with mixtures and mutations).", difficulty: 1 },
  { id: "reg-012", topic: "registration", levels: ["AAGO"], q: "A Rückpositiv is located:", choices: ["Behind the organist, often in the gallery rail", "Directly above the Hauptwerk", "At chest level above the music desk", "In a swell box in the tower"], answer: 0, explain: "The French equivalent is the Positif de dos.", difficulty: 1 },
  { id: "reg-013", topic: "registration", levels: ["AAGO"], q: "In the Werkprinzip organ, the Brustwerk is located:", choices: ["Behind the player's back", "At the top of the case", "In separate towers on either side", "Just above the keydesk, below the Hauptwerk"], answer: 3, explain: "Its small pipes, often with doors, sit at the player's 'chest'.", difficulty: 2 },
  { id: "reg-014", topic: "registration", levels: ["AAGO"], q: "The Werkprinzip refers to:", choices: ["Mechanical action with suspended keys", "The order in which stops are added in a crescendo", "Each division housed in its own case section, built on a principal of a different pitch", "A system of unified ranks"], answer: 2, explain: "Each Werk is visually and tonally distinct, e.g., Hauptwerk on 8', Brustwerk on 2'.", difficulty: 2 },
  { id: "reg-015", topic: "registration", levels: ["CAGO", "AAGO"], q: "The French term Montre corresponds to the English:", choices: ["Stopped flute", "Principal (Diapason)", "Trumpet", "Mixture"], answer: 1, explain: "Montre means 'display': these pipes usually stand in the façade.", difficulty: 1 },
  { id: "reg-016", topic: "registration", levels: ["CAGO", "AAGO"], q: "Compared with an open pipe of the same length, a stopped pipe sounds:", choices: ["An octave lower, with mainly odd-numbered harmonics", "An octave higher, with mainly even harmonics", "At the same pitch but softer", "A fifth lower"], answer: 0, explain: "A closed pipe acts like a quarter-wave resonator, favoring odd harmonics.", difficulty: 2 },
  { id: "reg-017", topic: "registration", levels: ["AAGO"], q: "A Quintadena is a stopped flue stop with a prominent:", choices: ["Octave (2nd harmonic)", "Seventeenth (5th harmonic)", "Fundamental only", "Twelfth (3rd harmonic)"], answer: 3, explain: "Its narrow stopped pipes speak with a strong 3rd harmonic.", difficulty: 2 },
  { id: "reg-018", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Voix céleste produces its undulating effect by:", choices: ["A mechanical tremulant", "Using reed pipes", "Being tuned slightly off from another string rank, producing beats", "Speaking an octave higher"], answer: 2, explain: "It is drawn with a unison string; the slight mistuning causes beats.", difficulty: 1 },
  { id: "reg-019", topic: "registration", levels: ["AAGO"], q: "A Cromorne (Krummhorn) is a reed with resonators that are:", choices: ["Conical and full-length", "Cylindrical and about half-length", "Very short, like a regal", "Double-length and harmonic"], answer: 1, explain: "Half-length cylindrical resonators emphasize odd harmonics, giving a clarinet-like tone.", difficulty: 2 },
  { id: "reg-020", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Clairon is a reed stop at which pitch?", choices: ["4'", "8'", "16'", "2'"], answer: 0, explain: "Clairon 4' sits above Trompette 8' and Bombarde 16'.", difficulty: 1 },
  { id: "reg-021", topic: "registration", levels: ["AAGO"], q: "A Flûte harmonique achieves its tone through pipes that are:", choices: ["Stopped with a chimney", "Conical and tapered", "Made of wood with inverted mouths", "Double length, with a small hole to make them overblow to the octave"], answer: 3, explain: "Cavaillé-Coll made these a feature of the French Romantic organ.", difficulty: 2 },
  { id: "reg-022", topic: "registration", levels: ["AAGO"], q: "In the pedal, a 10 2/3' Quint drawn with a 16' stop produces:", choices: ["A 64' effect", "An 8' effect", "A resultant 32' effect", "A 5 1/3' effect"], answer: 2, explain: "The two pitches (2nd and 3rd harmonics of 32') suggest the 32' fundamental.", difficulty: 2 },
  { id: "reg-023", topic: "registration", levels: ["CAGO", "AAGO"], q: "Which of these is a compound (multi-rank) stop?", choices: ["Gemshorn", "Fourniture", "Rohrflöte", "Posaune"], answer: 1, explain: "A Fourniture is a mixture; Scharf and Zimbel (Cymbale) are also mixtures.", difficulty: 1 },
  { id: "reg-025", topic: "registration", levels: ["CAGO", "AAGO"], q: "A Rohrflöte is:", choices: ["A stopped flute with a chimney in its cap", "An open conical flute", "A reed stop", "A string stop"], answer: 0, explain: "'Rohr' (tube) refers to the chimney, which brightens the stopped tone.", difficulty: 1 },
  { id: "reg-026", topic: "registration", levels: ["AAGO"], q: "A mutation stop is one that:", choices: ["Has more than one rank", "Is enclosed in a swell box", "Speaks only in the treble", "Sounds a pitch other than an octave of the fundamental"], answer: 3, explain: "Examples: Nazard, Tierce, Larigot; a mixture is compound rather than (necessarily) a single mutation.", difficulty: 1 },
  { id: "reg-027", topic: "registration", levels: ["AAGO"], q: "A mixture 'breaks' (repeats) in order to:", choices: ["Change temperament", "Add a tremolo", "Keep its highest pipes within a practical size range", "Increase the wind pressure"], answer: 2, explain: "As pitches rise, ranks drop back an octave so pipes do not become impossibly small.", difficulty: 2 },
  { id: "reg-028", topic: "registration", levels: ["AAGO"], q: "An Unda maris differs from a Voix céleste in that it is typically:", choices: ["A reed stop", "A flute or soft principal rank, usually tuned slightly flat", "A mixture", "Tuned exactly in unison"], answer: 1, explain: "'Wave of the sea' produces gentle beats with a unison flue.", difficulty: 2 },
  { id: "reg-029", topic: "registration", levels: ["AAGO"], q: "A 5 1/3' manual stop sounds:", choices: ["A fifth above 8' pitch", "A third above 8' pitch", "An octave below 8' pitch", "A twelfth above 8' pitch"], answer: 0, explain: "5 1/3' is the 3rd harmonic of 16'; it belongs to the 16' harmonic series.", difficulty: 2 },
  { id: "reg-030", topic: "registration", levels: ["AAGO"], q: "In the French Classical organ, a Récit de Nazard is a solo using:", choices: ["Trompette alone", "The Plein jeu", "Cromorne with Montre", "Flutes 8' and 4' plus the Nazard"], answer: 3, explain: "Solo 'récits' are named after their characteristic stop.", difficulty: 2 },
  { id: "reg-032", topic: "registration", levels: ["AAGO"], q: "Which stop is a short-resonator reed meant to imitate the human voice?", choices: ["Vox angelica", "Viola da gamba", "Vox humana", "Hautbois"], answer: 2, explain: "The Vox (or Voix) humana is usually used with tremulant; the Vox angelica is a soft string.", difficulty: 1 },

  // ===================== ORGAN REPERTOIRE =====================
  { id: "orep-001", topic: "organ-rep", levels: ["CAGO", "AAGO"], q: "Bach compiled most of the Orgelbüchlein during his years at:", choices: ["Leipzig", "Weimar", "Arnstadt", "Cöthen"], answer: 1, explain: "He planned 164 chorale preludes but completed only a fraction.", difficulty: 1 },
  { id: "orep-002", topic: "organ-rep", levels: ["AAGO"], q: "Bach's Clavier-Übung III (1739) is framed by:", choices: ["The Prelude and Fugue in E-flat ('St. Anne')", "The Passacaglia in C minor", "The Toccata and Fugue in D minor", "The Fantasia in G"], answer: 0, explain: "Between them come the catechism and Mass chorales and four duets.", difficulty: 2 },
  { id: "orep-003", topic: "organ-rep", levels: ["AAGO"], q: "The six Schübler Chorales are mostly:", choices: ["Fugues on chorale melodies", "Chorale partitas", "Pedal exercises", "Transcriptions of cantata movements"], answer: 3, explain: "'Wachet auf' (BWV 645) is from Cantata 140.", difficulty: 1 },
  { id: "orep-004", topic: "organ-rep", levels: ["AAGO"], q: "The Leipzig (or 'Great Eighteen') chorales have which BWV range?", choices: ["599-644", "645-650", "651-668", "669-689"], answer: 2, explain: "599-644 = Orgelbüchlein; 645-650 = Schübler; 669-689 = Clavier-Übung III chorales.", difficulty: 2 },
  { id: "orep-005", topic: "organ-rep", levels: ["AAGO"], q: "How many trio sonatas for organ did Bach write (BWV 525-530)?", choices: ["Four", "Six", "Eight", "Twelve"], answer: 1, explain: "They are thought to have served for the training of Wilhelm Friedemann Bach.", difficulty: 1 },
  { id: "orep-006", topic: "organ-rep", levels: ["AAGO"], q: "In 1705 Bach traveled from Arnstadt to Lübeck to hear:", choices: ["Dietrich Buxtehude", "Georg Böhm", "Johann Pachelbel", "Johann Adam Reincken"], answer: 0, explain: "Buxtehude was organist of the Marienkirche, famous for his Abendmusiken.", difficulty: 1 },
  { id: "orep-007", topic: "organ-rep", levels: ["AAGO"], q: "Jan Pieterszoon Sweelinck served as organist of:", choices: ["St. Bavo, Haarlem", "St. Jacobi, Hamburg", "Utrecht Cathedral", "The Oude Kerk, Amsterdam"], answer: 3, explain: "His pupils, including Scheidt and Scheidemann, founded the north German school.", difficulty: 2 },
  { id: "orep-008", topic: "organ-rep", levels: ["AAGO"], q: "Samuel Scheidt's landmark organ publication of 1624 is:", choices: ["Fiori musicali", "Hexachordum Apollinis", "Tabulatura nova", "Apparatus musico-organisticus"], answer: 2, explain: "Fiori musicali is Frescobaldi's; Hexachordum Apollinis is Pachelbel's.", difficulty: 2 },
  { id: "orep-009", topic: "organ-rep", levels: ["AAGO"], q: "Frescobaldi's Fiori musicali (1635) contains:", choices: ["Six trio sonatas", "Three organ Masses", "Twenty-four preludes", "Chorale partitas"], answer: 1, explain: "The Messa della Domenica, degli Apostoli, and della Madonna; Bach owned a copy.", difficulty: 2 },
  { id: "orep-010", topic: "organ-rep", levels: ["AAGO"], q: "The 'tiento' is a genre characteristic of which national school?", choices: ["Spanish", "Italian", "North German", "English"], answer: 0, explain: "Cabezón and Correa de Arauxo (Facultad orgánica, 1626) are key tiento composers.", difficulty: 1 },
  { id: "orep-011", topic: "organ-rep", levels: ["AAGO"], q: "François Couperin's Pièces d'orgue (1690) consist of:", choices: ["Three organ symphonies", "A book of Noëls", "Twelve preludes and fugues", "Messe pour les paroisses and Messe pour les couvents"], answer: 3, explain: "The parish Mass is built on plainchant; the convent Mass is freely composed.", difficulty: 1 },
  { id: "orep-012", topic: "organ-rep", levels: ["AAGO"], q: "Nicolas de Grigny, whose Premier livre d'orgue (1699) Bach copied, was organist at:", choices: ["Saint-Gervais, Paris", "Chartres Cathedral", "Reims Cathedral", "Versailles"], answer: 2, explain: "Couperin was at Saint-Gervais.", difficulty: 2 },
  { id: "orep-014", topic: "organ-rep", levels: ["AAGO"], q: "Mendelssohn's Six Organ Sonatas are his opus:", choices: ["37", "65", "52", "80"], answer: 1, explain: "Published in 1845, they were commissioned by an English publisher; Op. 37 is the Three Preludes and Fugues.", difficulty: 1 },
  { id: "orep-015", topic: "organ-rep", levels: ["AAGO"], q: "Liszt's Fantasy and Fugue on 'Ad nos, ad salutarem undam' is based on a chorale from an opera by:", choices: ["Meyerbeer", "Wagner", "Verdi", "Gounod"], answer: 0, explain: "The chorale is sung by three Anabaptists in Le prophète.", difficulty: 2 },
  { id: "orep-016", topic: "organ-rep", levels: ["AAGO"], q: "Julius Reubke's Sonata on the 94th Psalm was written by a pupil of:", choices: ["Mendelssohn", "Brahms", "Rheinberger", "Liszt"], answer: 3, explain: "Reubke died in 1858 at age 24.", difficulty: 2 },
  { id: "orep-017", topic: "organ-rep", levels: ["AAGO"], q: "Which piece is NOT part of Franck's Six Pièces?", choices: ["Grande pièce symphonique", "Prélude, fugue et variation", "Pièce héroïque", "Pastorale"], answer: 2, explain: "Pièce héroïque belongs to the Trois Pièces written for the 1878 Paris Exposition (Trocadéro).", difficulty: 2 },
  { id: "orep-018", topic: "organ-rep", levels: ["AAGO"], q: "César Franck's Trois Chorals were completed in:", choices: ["1862", "1890, the year of his death", "1878", "1868"], answer: 1, explain: "They were his last works for organ.", difficulty: 2 },
  { id: "orep-019", topic: "organ-rep", levels: ["AAGO"], q: "Franck was titular organist of which Paris church?", choices: ["Sainte-Clotilde", "Saint-Sulpice", "La Trinité", "La Madeleine"], answer: 0, explain: "Tournemire and later Langlais succeeded him there.", difficulty: 1 },
  { id: "orep-020", topic: "organ-rep", levels: ["AAGO"], q: "Widor's famous Toccata is the finale of which organ symphony?", choices: ["No. 6", "No. 9 (Gothique)", "No. 1", "No. 5"], answer: 3, explain: "Widor wrote ten organ symphonies and was organist of Saint-Sulpice for over 60 years.", difficulty: 1 },
  { id: "orep-021", topic: "organ-rep", levels: ["AAGO"], q: "How many organ symphonies did Louis Vierne write?", choices: ["Ten", "Four", "Six", "Eight"], answer: 2, explain: "Vierne was organist of Notre-Dame from 1900 until his death at the console in 1937.", difficulty: 1 },
  { id: "orep-022", topic: "organ-rep", levels: ["AAGO"], q: "Vierne's 'Carillon de Westminster' comes from his:", choices: ["Pièces en style libre", "Pièces de fantaisie", "Symphony No. 3", "Messe solennelle"], answer: 1, explain: "It is in the third suite of the 24 Pièces de fantaisie.", difficulty: 2 },
  { id: "orep-023", topic: "organ-rep", levels: ["AAGO"], q: "Charles Tournemire's L'Orgue mystique is organized around:", choices: ["The chant propers of the liturgical year", "Lutheran chorales", "Psalms in metrical paraphrase", "Bird songs"], answer: 0, explain: "Its 51 offices paraphrase the Gregorian propers of Sundays and feasts.", difficulty: 2 },
  { id: "orep-024", topic: "organ-rep", levels: ["AAGO"], q: "Duruflé's Prélude et fugue sur le nom d'Alain honors:", choices: ["Marie-Claire Alain", "Albert Alain, the composer's teacher", "Olivier Alain", "Jehan Alain, killed in 1940"], answer: 3, explain: "The subject is derived from the letters of ALAIN; the work quotes Alain's Litanies.", difficulty: 1 },
  { id: "orep-025", topic: "organ-rep", levels: ["AAGO"], q: "Duruflé's Prélude, Adagio et Choral varié is based on which chant?", choices: ["Victimae paschali laudes", "Salve Regina", "Veni Creator Spiritus", "Ave maris stella"], answer: 2, explain: "It is his Op. 4.", difficulty: 1 },
  { id: "orep-026", topic: "organ-rep", levels: ["AAGO"], q: "Duruflé was titular organist of:", choices: ["Notre-Dame", "Saint-Étienne-du-Mont", "Sainte-Trinité", "Saint-Sulpice"], answer: 1, explain: "He held the post with his wife, Marie-Madeleine Duruflé.", difficulty: 2 },
  { id: "orep-027", topic: "organ-rep", levels: ["AAGO"], q: "Which of these is by Jehan Alain?", choices: ["Litanies", "Dieu parmi nous", "Carillon de Westminster", "Suite gothique"], answer: 0, explain: "'Dieu parmi nous' is Messiaen, 'Carillon' is Vierne, Suite gothique is Boëllmann.", difficulty: 1 },
  { id: "orep-028", topic: "organ-rep", levels: ["AAGO"], q: "'Dieu parmi nous' is the final movement of which Messiaen cycle?", choices: ["L'Ascension", "Les Corps glorieux", "Messe de la Pentecôte", "La Nativité du Seigneur"], answer: 3, explain: "La Nativité (1935) has nine meditations on the birth of Christ.", difficulty: 1 },
  { id: "orep-029", topic: "organ-rep", levels: ["AAGO"], q: "Messiaen was titular organist of which Paris church for over 60 years?", choices: ["Sainte-Clotilde", "Saint-Eustache", "La Sainte-Trinité", "Saint-Augustin"], answer: 2, explain: "He held the post from 1931 until his death in 1992.", difficulty: 1 },
  { id: "orep-030", topic: "organ-rep", levels: ["AAGO", "FAGO"], q: "Messiaen's 'modes of limited transposition' are scales that:", choices: ["Use only the white keys", "Return to the same pitch collection after fewer than twelve transpositions", "Contain exactly five notes", "Are derived from Gregorian modes"], answer: 1, explain: "The whole-tone scale (Mode 1) has only two distinct transpositions; the octatonic (Mode 2) has three.", difficulty: 2 },
  { id: "orep-031", topic: "organ-rep", levels: ["AAGO"], q: "Brahms's Eleven Chorale Preludes are his opus:", choices: ["122", "45", "98", "115"], answer: 0, explain: "Written in 1896, they were his last completed works and were published posthumously.", difficulty: 2 },
  { id: "orep-032", topic: "organ-rep", levels: ["AAGO"], q: "Max Reger's Fantasy and Fugue on B-A-C-H is his opus:", choices: ["52", "59", "127", "46"], answer: 3, explain: "Op. 52 is a set of chorale fantasias; Op. 127 is the Introduction, Passacaglia and Fugue in E minor.", difficulty: 3 },
  { id: "orep-033", topic: "organ-rep", levels: ["AAGO"], q: "Charles Ives's Variations on 'America' were composed when he was:", choices: ["A Yale student in his twenties", "Middle-aged, after retiring from insurance", "A teenager (c. 1891)", "Composing for the 1939 World's Fair"], answer: 2, explain: "Ives wrote them around 1891, at about 17, and played them in Brewster, NY.", difficulty: 2 },
  { id: "orep-034", topic: "organ-rep", levels: ["AAGO"], q: "Leo Sowerby won the Pulitzer Prize in 1946 for:", choices: ["Symphony in G for organ", "The Canticle of the Sun", "Comes Autumn Time", "Pageant"], answer: 1, explain: "Sowerby was organist-choirmaster of St. James Cathedral, Chicago.", difficulty: 2 },
  { id: "orep-035", topic: "organ-rep", levels: ["AAGO"], q: "Florence Price was the first African-American woman to:", choices: ["Have a symphony performed by a major American orchestra", "Win the Pulitzer Prize in music", "Conduct the New York Philharmonic", "Teach at Juilliard"], answer: 0, explain: "The Chicago Symphony premiered her Symphony in E minor in 1933; she also wrote substantial organ music.", difficulty: 2 },
  { id: "orep-038", topic: "organ-rep", levels: ["AAGO"], q: "Marcel Dupré's Op. 7 consists of:", choices: ["Symphonie-Passion", "Le Chemin de la Croix", "Variations sur un Noël", "Three Preludes and Fugues"], answer: 3, explain: "The B major prelude and fugue is among the most demanding in the repertoire.", difficulty: 2 },
  { id: "orep-039", topic: "organ-rep", levels: ["AAGO"], q: "Georg Böhm, whose chorale partitas influenced the young Bach, worked in:", choices: ["Lübeck", "Hamburg", "Lüneburg", "Nuremberg"], answer: 2, explain: "Böhm was organist of the Johanniskirche, Lüneburg, where Bach was a schoolboy.", difficulty: 2 },
  { id: "orep-041", topic: "organ-rep", levels: ["AAGO"], q: "Who among these was a pupil of Marcel Dupré?", choices: ["Louis Vierne", "Olivier Messiaen", "César Franck", "Alexandre Guilmant"], answer: 1, explain: "Messiaen, Alain, and Langlais all studied organ with Dupré at the Paris Conservatoire.", difficulty: 1 },

  // ===================== ORCHESTRATION =====================
  { id: "orch-001", topic: "orchestration", levels: ["FAGO"], q: "A clarinet in B♭ sounds:", choices: ["A major second lower than written", "A minor third lower than written", "A perfect fifth lower than written", "As written"], answer: 0, explain: "The A clarinet sounds a minor third lower.", difficulty: 1 },
  { id: "orch-002", topic: "orchestration", levels: ["FAGO"], q: "A horn in F sounds:", choices: ["A perfect fourth lower than written", "A major second lower than written", "An octave lower than written", "A perfect fifth lower than written"], answer: 3, explain: "Parts for horn in F are therefore written a fifth above concert pitch.", difficulty: 1 },
  { id: "orch-003", topic: "orchestration", levels: ["FAGO"], q: "The English horn sounds:", choices: ["A major sixth lower than written", "An octave lower than written", "A perfect fifth lower than written", "A major second lower than written"], answer: 2, explain: "It is an alto oboe in F.", difficulty: 1 },
  { id: "orch-004", topic: "orchestration", levels: ["FAGO"], q: "An alto saxophone in E♭ sounds:", choices: ["A minor third higher than written", "A major sixth lower than written", "A perfect fifth lower than written", "A major ninth lower than written"], answer: 1, explain: "The E♭ clarinet, by contrast, sounds a minor third higher.", difficulty: 2 },
  { id: "orch-005", topic: "orchestration", levels: ["FAGO"], q: "A bass clarinet in B♭, written in treble clef, sounds:", choices: ["A major ninth lower than written", "A major second lower than written", "An octave lower than written", "Two octaves lower than written"], answer: 0, explain: "It sounds an octave below the B♭ soprano clarinet's transposition.", difficulty: 2 },
  { id: "orch-006", topic: "orchestration", levels: ["FAGO"], q: "The piccolo sounds:", choices: ["As written", "Two octaves higher than written", "A fifth higher than written", "An octave higher than written"], answer: 3, explain: "It is written an octave lower to avoid excessive ledger lines.", difficulty: 1 },
  { id: "orch-007", topic: "orchestration", levels: ["FAGO"], q: "The double bass sounds:", choices: ["As written", "Two octaves lower than written", "An octave lower than written", "A fifth lower than written"], answer: 2, explain: "The contrabassoon and guitar also sound an octave lower.", difficulty: 1 },
  { id: "orch-008", topic: "orchestration", levels: ["FAGO"], q: "The glockenspiel sounds:", choices: ["One octave higher than written", "Two octaves higher than written", "As written", "An octave lower than written"], answer: 1, explain: "The xylophone usually sounds one octave higher; the celesta one octave higher.", difficulty: 2 },
  { id: "orch-010", topic: "orchestration", levels: ["FAGO"], q: "What is the lowest note of the standard modern oboe?", choices: ["B♭3 (just below middle C)", "C4 (middle C)", "G3", "D4"], answer: 0, explain: "The oboe's range extends upward roughly two and a half octaves.", difficulty: 2 },
  { id: "orch-011", topic: "orchestration", levels: ["FAGO"], q: "What is the lowest note of the standard bassoon?", choices: ["C2", "E1", "D2", "B♭1"], answer: 3, explain: "The contrabassoon sounds an octave lower, to B♭0.", difficulty: 2 },
  { id: "orch-012", topic: "orchestration", levels: ["FAGO"], q: "What is the lowest (written) note of the B♭ soprano clarinet?", choices: ["C4", "D3", "E3", "G3"], answer: 2, explain: "Written E3 sounds D3 on the B♭ clarinet.", difficulty: 2 },
  { id: "orch-013", topic: "orchestration", levels: ["FAGO"], q: "The viola's open strings are:", choices: ["G3, D4, A4, E5", "C3, G3, D4, A4", "C2, G2, D3, A3", "E1, A1, D2, G2"], answer: 1, explain: "Violin: G-D-A-E; cello: C-G-D-A an octave below viola; bass: E-A-D-G.", difficulty: 1 },
  { id: "orch-014", topic: "orchestration", levels: ["FAGO"], q: "Which clef is the viola's principal clef?", choices: ["Alto clef", "Tenor clef", "Treble clef", "Bass clef"], answer: 0, explain: "Viola uses alto (C clef on the middle line), moving to treble for high passages.", difficulty: 1 },
  { id: "orch-015", topic: "orchestration", levels: ["FAGO"], q: "How many pedals does the modern concert (double-action) harp have?", choices: ["Five", "Eight", "Twelve", "Seven"], answer: 3, explain: "One pedal per note name; each pedal sets that pitch class to flat, natural, or sharp in all octaves.", difficulty: 2 },
  { id: "orch-016", topic: "orchestration", levels: ["FAGO"], q: "Which of these instruments is non-transposing?", choices: ["Trumpet in B♭", "Horn in F", "Trombone", "Clarinet in A"], answer: 2, explain: "Trombone and tuba parts are written at concert pitch.", difficulty: 1 },

  // ===================== THEORY / FUGUE / COUNTERPOINT / PERFORMANCE / HISTORY =====================
  { id: "fugue-001", topic: "fugue", levels: ["AAGO", "FAGO"], q: "A 'tonal answer' in a fugue is one that:", choices: ["Transposes the subject exactly to the dominant", "Alters some intervals of the subject, typically exchanging tonic and dominant", "Inverts the subject", "States the subject in augmentation"], answer: 1, explain: "A real answer is an exact transposition; a tonal answer adjusts it to keep the tonic key clear.", difficulty: 2 },
  { id: "fugue-002", topic: "fugue", levels: ["AAGO", "FAGO"], q: "A countersubject is:", choices: ["A recurring counterpoint that accompanies the subject or answer", "The answer at the dominant", "A free passage between entries", "The subject played upside down"], answer: 0, explain: "A regular countersubject is usually written in invertible counterpoint with the subject.", difficulty: 1 },
  { id: "fugue-003", topic: "fugue", levels: ["AAGO", "FAGO"], q: "Overlapping entries of the subject, before the previous entry has finished, are called:", choices: ["Episode", "Codetta", "Pedal point", "Stretto"], answer: 3, explain: "Stretto is often used to build intensity near the end of a fugue.", difficulty: 1 },
  { id: "fugue-004", topic: "fugue", levels: ["AAGO", "FAGO"], q: "A subject stated in note values twice as long is said to be in:", choices: ["Diminution", "Retrograde", "Augmentation", "Inversion"], answer: 2, explain: "Diminution halves the values; inversion turns intervals upside down.", difficulty: 1 },
  { id: "fugue-005", topic: "fugue", levels: ["AAGO", "FAGO"], q: "In a fugue, a passage that does not contain a complete statement of the subject, often modulating, is a(n):", choices: ["Exposition", "Episode", "Stretto", "Counter-exposition"], answer: 1, explain: "Episodes are often built sequentially from motives of the subject or countersubject.", difficulty: 1 },
  { id: "cpt-001", topic: "counterpoint", levels: ["AAGO", "FAGO"], q: "In invertible counterpoint at the octave, which consonance becomes a dissonance when the voices are inverted?", choices: ["Perfect fifth", "Major third", "Minor sixth", "Octave"], answer: 0, explain: "Intervals invert to their complement summing to 9: a fifth becomes a fourth, which is dissonant above the bass.", difficulty: 2 },
  { id: "cpt-002", topic: "counterpoint", levels: ["FAGO"], q: "Fux's Gradus ad Parnassum (1725) teaches counterpoint through how many species?", choices: ["Four", "Three", "Seven", "Five"], answer: 3, explain: "1:1, 2:1, 4:1, syncopation (suspensions), and florid.", difficulty: 1 },
  { id: "cpt-003", topic: "counterpoint", levels: ["FAGO"], q: "Fourth-species counterpoint is principally concerned with:", choices: ["Note against note", "Two notes against one", "Syncopation and suspensions", "Florid mixed rhythms"], answer: 2, explain: "Ties across the bar create suspensions that are prepared, struck, and resolved downward by step.", difficulty: 1 },
  { id: "cpt-004", topic: "counterpoint", levels: ["FAGO"], q: "In strict style, how must a suspension dissonance resolve?", choices: ["Up by step", "Down by step", "By leap of a third", "By leap to an octave"], answer: 1, explain: "Preparation (consonant), suspension (dissonant, on the strong beat), resolution (down by step).", difficulty: 1 },
  { id: "cpt-005", topic: "counterpoint", levels: ["FAGO"], q: "The nota cambiata figure is distinctive because:", choices: ["A dissonance is left by leap of a third, then the line returns by step", "A dissonance resolves upward by step", "A consonance is approached by leap from both sides", "A note is repeated on a strong beat"], answer: 0, explain: "The classic shape steps down to a dissonance, leaps down a third, then steps up.", difficulty: 3 },
  { id: "cpt-006", topic: "counterpoint", levels: ["FAGO"], q: "In 16th-century two-voice counterpoint, the perfect fourth is treated as:", choices: ["A perfect consonance", "An imperfect consonance", "A consonance only on strong beats", "A dissonance"], answer: 3, explain: "Above the lowest voice the fourth is dissonant; it can be consonant between upper voices.", difficulty: 2 },
  { id: "cpt-007", topic: "counterpoint", levels: ["FAGO"], q: "In first-species counterpoint, the first and last intervals should be:", choices: ["Imperfect consonances", "Thirds only", "Perfect consonances", "Any consonance"], answer: 2, explain: "Unison, octave, or (at the start) fifth frame the exercise.", difficulty: 1 },
  { id: "cpt-008", topic: "counterpoint", levels: ["FAGO"], q: "An échappée (escape tone) is:", choices: ["A note approached and left by leap", "A non-chord tone approached by step and left by leap in the opposite direction", "A tied note that resolves down by step", "A note that anticipates the next chord"], answer: 1, explain: "The appoggiatura does the reverse: approached by leap, resolved by step.", difficulty: 2 },
  { id: "thy-001", topic: "theory", levels: ["AAGO", "FAGO"], q: "The Neapolitan sixth chord is:", choices: ["A major triad on the lowered second degree, in first inversion", "A minor triad on the second degree, in first inversion", "A diminished seventh on the raised fourth", "A dominant seventh on the flat sixth"], answer: 0, explain: "In C minor: F-A♭-D♭, typically leading to V.", difficulty: 1 },
  { id: "thy-002", topic: "theory", levels: ["AAGO", "FAGO"], q: "Which augmented sixth chord contains only three distinct pitches (♭6, 1, ♯4)?", choices: ["French", "German", "Swiss", "Italian"], answer: 3, explain: "The French adds scale degree 2; the German adds ♭3 (♭3 spelled as ♯2 is sometimes called 'Swiss').", difficulty: 2 },
  { id: "thy-003", topic: "theory", levels: ["AAGO"], q: "A cadence V-vi is called:", choices: ["Plagal", "Half", "Deceptive", "Phrygian"], answer: 2, explain: "The ear expects I but hears vi instead.", difficulty: 1 },
  { id: "thy-004", topic: "theory", levels: ["AAGO"], q: "A Phrygian half cadence in minor typically moves:", choices: ["V to i", "iv6 to V", "iv to i", "ii to V7"], answer: 1, explain: "The bass descends by half step from ♭6 to 5.", difficulty: 2 },
  { id: "thy-005", topic: "theory", levels: ["AAGO"], q: "A major tonic chord ending a piece in a minor key is called a:", choices: ["Picardy third", "Phrygian resolution", "Plagal third", "Deceptive third"], answer: 0, explain: "The tierce de Picardie was common in Renaissance and Baroque music.", difficulty: 1 },
  { id: "thy-006", topic: "theory", levels: ["AAGO", "FAGO"], q: "In a minor-key sonata-form exposition, the second theme group typically appears in:", choices: ["The dominant minor", "The parallel major", "The subdominant", "The relative major"], answer: 3, explain: "In major keys the second group usually moves to the dominant.", difficulty: 2 },
  { id: "thy-007", topic: "theory", levels: ["AAGO"], q: "A hemiola is:", choices: ["A melodic leap of a sixth", "A chord with an added sixth", "A temporary shift from two groups of three beats to three groups of two", "A repeated bass pattern"], answer: 2, explain: "It is common at cadences in Baroque triple-meter dances.", difficulty: 1 },
  { id: "perf-001", topic: "performance", levels: ["AAGO"], q: "Notes inégales is a French Baroque practice in which:", choices: ["All notes are played detached", "Stepwise pairs of short notes are played long-short", "Ornaments begin on the main note", "Dotted rhythms are played evenly"], answer: 1, explain: "It typically applied to the note values moving at half the beat in conjunct motion.", difficulty: 1 },
  { id: "perf-002", topic: "performance", levels: ["AAGO"], q: "In early keyboard fingering (e.g., English virginalists), scale passages were typically played with:", choices: ["Paired fingers such as 3-4-3-4", "Thumb crossings on every third note", "Only the thumb and fifth finger", "Modern 1-2-3-1-2-3-4 patterns"], answer: 0, explain: "Paired fingering naturally creates grouping and articulation.", difficulty: 2 },
  { id: "perf-003", topic: "performance", levels: ["AAGO", "FAGO"], q: "Quarter-comma meantone temperament makes which interval pure?", choices: ["Perfect fifths", "Minor thirds", "Octaves and fifths", "Major thirds"], answer: 3, explain: "Each fifth is narrowed by a quarter of the syntonic comma so that four fifths yield a pure major third.", difficulty: 2 },
  { id: "perf-004", topic: "performance", levels: ["AAGO", "FAGO"], q: "In a meantone tuning with the usual notes (E♭ to G♯), the 'wolf' fifth falls between:", choices: ["C and G", "F and C", "G♯ and E♭", "B and F♯"], answer: 2, explain: "The leftover interval is badly wide, making remote keys unusable.", difficulty: 3 },
  { id: "perf-005", topic: "performance", levels: ["AAGO", "FAGO"], q: "The Pythagorean comma is the amount by which:", choices: ["Four pure fifths exceed a pure major third plus two octaves", "Twelve pure fifths exceed seven octaves", "A major whole tone exceeds a minor whole tone", "An octave exceeds two tritones"], answer: 1, explain: "It is about 23.5 cents; the syntonic comma (about 21.5 cents) is the fifths-versus-third discrepancy.", difficulty: 3 },
  { id: "perf-006", topic: "performance", levels: ["AAGO", "FAGO"], q: "Compared with pure intervals, equal-tempered major thirds are:", choices: ["About 14 cents wide", "About 2 cents narrow", "Pure", "About 14 cents narrow"], answer: 0, explain: "Equal-tempered fifths are only about 2 cents narrow, but thirds are notably wide.", difficulty: 2 },
  { id: "hist-001", topic: "history", levels: ["ChM", "AAGO"], q: "Guido of Arezzo derived the solmization syllables ut-re-mi-fa-sol-la from:", choices: ["The Te Deum", "The Magnificat", "The Litany of the Saints", "The hymn Ut queant laxis for St. John the Baptist"], answer: 3, explain: "Each phrase of the hymn begins one step higher.", difficulty: 1 },
  { id: "hist-002", topic: "history", levels: ["ChM", "AAGO"], q: "The first complete polyphonic setting of the Mass Ordinary by a single known composer is:", choices: ["Dufay's Missa Se la face ay pale", "Josquin's Missa Pange lingua", "Machaut's Messe de Nostre Dame", "Pérotin's Viderunt omnes"], answer: 2, explain: "Machaut composed it in the mid-14th century.", difficulty: 1 },
  { id: "hist-003", topic: "history", levels: ["ChM", "AAGO"], q: "Léonin and Pérotin are associated with organum at:", choices: ["St. Martial of Limoges", "Notre-Dame de Paris", "Santiago de Compostela", "Winchester"], answer: 1, explain: "The Magnus liber organi is the repertory of the Notre Dame school.", difficulty: 1 },
  { id: "hist-004", topic: "history", levels: ["ChM", "AAGO"], q: "Fauxbourdon is a 15th-century technique based largely on:", choices: ["Parallel first-inversion (6/3) sonorities", "Parallel fifths and octaves", "A cantus firmus in long notes in the bass", "Imitation at the unison"], answer: 0, explain: "Two written voices a sixth apart were supplemented by an improvised voice a fourth below the top.", difficulty: 2 },
  { id: "hist-005", topic: "history", levels: ["ChM", "AAGO"], q: "A 'parody' (imitation) Mass is one that:", choices: ["Uses a single chant melody paraphrased in all voices", "Places a borrowed melody in long notes in the tenor", "Is written in a deliberately comic style", "Reworks multiple voices of an existing polyphonic piece"], answer: 3, explain: "Paraphrase Masses (like Josquin's Missa Pange lingua) elaborate a single melody; cantus firmus Masses place it in one voice.", difficulty: 2 },
  { id: "hist-006", topic: "history", levels: ["ChM", "AAGO"], q: "The Florentine Camerata of the late 16th century is associated with:", choices: ["Polychoral music", "The invention of the fugue", "Monody (solo song over basso continuo)", "The restoration of chant"], answer: 2, explain: "Their ideas on ancient Greek drama helped lead to early opera.", difficulty: 1 },
  { id: "hist-007", topic: "history", levels: ["ChM"], q: "The 19th-century Cecilian movement, centered in Germany, sought to:", choices: ["Introduce orchestral Masses into the liturgy", "Reform Catholic church music toward chant and a cappella polyphony", "Promote congregational hymn singing in Lutheran churches", "Develop the theatre organ"], answer: 1, explain: "It looked to Palestrina as a model of liturgical propriety.", difficulty: 2 },
  { id: "hist-008", topic: "history", levels: ["ChM", "AAGO"], q: "Mendelssohn's 1829 performance of which work sparked the 19th-century Bach revival?", choices: ["St. Matthew Passion", "Mass in B minor", "Christmas Oratorio", "The Art of Fugue"], answer: 0, explain: "He conducted it in Berlin, about a century after its premiere.", difficulty: 1 },
  { id: "hist-009", topic: "history", levels: ["ChM", "AAGO"], q: "The 14th-century treatise associated with the term 'Ars nova' is attributed to:", choices: ["Guillaume de Machaut", "Johannes de Garlandia", "Franco of Cologne", "Philippe de Vitry"], answer: 3, explain: "Ars nova introduced new rhythmic notation, including duple divisions.", difficulty: 2 },
  { id: "hist-010", topic: "history", levels: ["ChM", "AAGO"], q: "Sprechstimme, a technique between speech and song, is associated with:", choices: ["Debussy's Pelléas et Mélisande", "Stravinsky's Les noces", "Schoenberg's Pierrot lunaire", "Ravel's L'enfant et les sortilèges"], answer: 2, explain: "Berg also used it in Wozzeck.", difficulty: 1 },
  { id: "hist-011", topic: "history", levels: ["ChM", "AAGO"], q: "The Venetian polychoral style (cori spezzati) is chiefly associated with:", choices: ["The Sistine Chapel", "St. Mark's Basilica", "Notre-Dame de Paris", "The Thomaskirche, Leipzig"], answer: 1, explain: "Willaert and the Gabrielis exploited the basilica's divided choir lofts.", difficulty: 1 }
];
